const lessons = [
{"num": 1, "time": "00:00:00,000 --> 00:00:23,820", "arabic": "الْمُؤْمِنُ مُبْتَلًى، وَهَلْ مِنَ الْإِيمَانِ أَنْ تُصَلِّيَ وَالدِّمَاءُ تَسِيلُ مِنْ ظَهْرِكَ؟", "segs": [{"ar": "الْمُؤْمِنُ مُبْتَلًى،", "uz": "Mo'min sinaladi,"}, {"ar": "وَهَلْ مِنَ الْإِيمَانِ أَنْ تُصَلِّيَ وَالدِّمَاءُ تَسِيلُ مِنْ ظَهْرِكَ؟", "uz": "orqangdan qon oqib turgan holda namoz o'qishing imondanmi?"}], "full_uz": "Mo'min sinaladi, orqangdan qon oqib turgan holda namoz o'qishing imondanmi?", "note": null},
{"num": 3, "time": "00:00:23,820 --> 00:00:38,299", "arabic": "أَجَلْ، قَدْ صَلَّى عُمَرُ بْنُ الْخَطَّابِ وَجُرْحُهُ يَنْزِفُ دَمَهُ، أَلَمْ تَسْمَعْ بِقِصَّتِهِ يَا قَاضِيَ الْقُضَاةِ؟ وَفَوْقَ كُلِّ ذِي عِلْمٍ عَلِيمٌ.", "segs": [{"ar": "أَجَلْ،", "uz": "Ha,"}, {"ar": "قَدْ صَلَّى عُمَرُ بْنُ الْخَطَّابِ وَجُرْحُهُ يَنْزِفُ دَمَهُ،", "uz": "Umar ibn al-Xattob yarasidan qon oqayotgan holda namoz o'qigan,"}, {"ar": "أَلَمْ تَسْمَعْ بِقِصَّتِهِ يَا قَاضِيَ الْقُضَاةِ؟", "uz": "uning voqeasini eshitmaganmisiz, ey qozilar qozisi?"}, {"ar": "وَفَوْقَ كُلِّ ذِي عِلْمٍ عَلِيمٌ.", "uz": "Har bir ilm egasidan ustunroq bilimdon bor."}], "full_uz": "Ha, Umar ibn al-Xattob yarasidan qon oqayotgan holda namoz o'qigan, uning voqeasini eshitmaganmisiz, ey qozilar qozisi? Har bir ilm egasidan ustunroq bilimdon bor.", "note": "\"وَفَوْقَ كُلِّ ذِي عِلْمٍ عَلِيمٌ\" — Qur'on, Yusuf surasi, 76-oyat."},
{"num": 7, "time": "00:00:38,299 --> 00:01:11,180", "arabic": "يَا إِسْحَاقُ، تَخْرُجُ إِلَى الْغَوْغَاءِ الْمُتَجَمِّعِينَ أَمَامَ الْقَصْرِ، وَتُخْبِرُهُمْ أَنَّ ابْنَ أَخِيكَ بِخَيْرٍ، وَتَطْلُبُ مِنْهُمُ الِانْصِرَافَ، عِنْدَهَا تَأْتِي لَهُنَا فَتَأْخُذُ ابْنَ أَخِيكَ وَتَنْصَرِفُهُ. فَهِمْتَ؟", "segs": [{"ar": "يَا إِسْحَاقُ، تَخْرُجُ إِلَى الْغَوْغَاءِ الْمُتَجَمِّعِينَ أَمَامَ الْقَصْرِ", "uz": "Ey Ishoq, saroy oldida to'plangan olomon oldiga chiqasan"}, {"ar": "وَتُخْبِرُهُمْ أَنَّ ابْنَ أَخِيكَ بِخَيْرٍ، وَتَطْلُبُ مِنْهُمُ الِانْصِرَافَ", "uz": "va ularga jiyaning sog'-omon ekanini aytib, tarqalishlarini so'raysan"}, {"ar": "عِنْدَهَا تَأْتِي لَهُنَا فَتَأْخُذُ ابْنَ أَخِيكَ وَتَنْصَرِفُهُ. فَهِمْتَ؟", "uz": "shundan so'ng bu yerga kelib jiyaningni olib, uni jo'natasan. Tushundingmi?"}], "full_uz": "Ey Ishoq, saroy oldida to'plangan olomon oldiga chiqib, ularga jiyaning sog'-omon ekanini aytasan va tarqalishlarini so'raysan. Shundan so'ng bu yerga kelib jiyaningni olib, uni jo'natasan. Tushundingmi?", "note": null},
{"num": 16, "time": "00:01:18,379 --> 00:01:44,379", "arabic": "مَا الَّذِي يَشْغَلُ بَالَ أَمِيرِ الْمُؤْمِنِينَ أَعَزَّهُ اللَّهُ؟", "segs": null, "full_uz": "Mo'minlar amirining (Alloh uni aziz qilsin) fikrini nima band qilyapti?", "note": null},
{"num": 17, "time": "00:01:48,379 --> 00:01:50,140", "arabic": "أُفَكِّرُ بِمَا جَرَى لَهُمْ.", "segs": null, "full_uz": "Ularga bo'lgan voqea haqida o'ylayapman.", "note": null},
{"num": 18, "time": "00:01:50,140 --> 00:01:53,699", "arabic": "أَتَقْصِدُ مَا جَرَى لِأَحْمَدَ بْنِ حَنْبَلٍ؟", "segs": null, "full_uz": "Ahmad ibn Hanbalga bo'lgan voqeani nazarda tutyapsizmi?", "note": null},
{"num": 19, "time": "00:01:53,699 --> 00:02:04,819", "arabic": "أَجَلْ يَا جَعْفَرُ، رَأَيْتُ فِي وَجْهِ ذَلِكَ الرَّجُلِ ثَبَاتًا وَإِخْلَاصًا.", "segs": [{"ar": "أَجَلْ يَا جَعْفَرُ،", "uz": "Ha, ey Ja'far,"}, {"ar": "رَأَيْتُ فِي وَجْهِ ذَلِكَ الرَّجُلِ ثَبَاتًا وَإِخْلَاصًا.", "uz": "o'sha odamning yuzida matonat va ixlosni ko'rdim."}], "full_uz": "Ha, ey Ja'far, o'sha odamning yuzida matonat va ixlosni ko'rdim.", "note": null},
{"num": 21, "time": "00:02:04,819 --> 00:02:07,379", "arabic": "لَا تَجِدُ فِيهِ مَا يُوجَدُ عِنْدَ صَاحِبِ بِدْعَةٍ.", "segs": null, "full_uz": "Unda bid'at egasida bo'ladigan narsalarni topmaysiz.", "note": null},
{"num": 22, "time": "00:02:07,379 --> 00:02:11,379", "arabic": "لَكِنْ مَا الْعَمَلُ إِنْ كَانَتْ حَاشِيَةُ الْقَصْرِ ضِدَّهُ؟", "segs": null, "full_uz": "Lekin saroy atrofidagilar unga qarshi bo'lsa, nima qilish kerak?", "note": null},
{"num": 23, "time": "00:02:16,120 --> 00:02:17,840", "arabic": "إِلَّا أَنْتَ يَا مَوْلَايَ.", "segs": null, "full_uz": "Sizdan boshqa hammasi, ey xo'jayinim.", "note": null},
{"num": 24, "time": "00:02:17,840 --> 00:02:22,379", "arabic": "لَا عِلْمَ لِي بِهَذَا الْأَمْرِ، لِهَذَا الْعِلْمِ رِجَالُهُ.", "segs": null, "full_uz": "Bu ishdan xabarim yo'q, bu ilmning o'z ahli bor.", "note": null},
{"num": 26, "time": "00:02:22,379 --> 00:02:43,159", "arabic": "لَقَدِ اجْتَمَعُوا عَلَى أَنَّ الرَّجُلَ مُبْتَدِعٌ، بَلْ كَافِرٌ وَضَالٌّ كَمَا يَقُولُونَ، وَإِنْ كَانَ الْأَمْرُ كَذَلِكَ إِلَّا أَنَّهُ أَفْهَمَهُمْ وَلَمْ يَمْلِكُوا أَمَامَهُ رَدًّا، وَلَمْ يَثْبُتُوا أَمَامَ أَدِلَّتِهِ، فَلَمَّا عَجَزُوا وَضَعُوهُ تَحْتَ السِّيَاطِ حَتَّى يُقِرَّ بِكُرْهٍ بِمَا لَمْ يَسْتَطِيعُوا إِقْنَاعَهُ بِهِ حُجَّةً وَدَلِيلًا.", "segs": [{"ar": "لَقَدِ اجْتَمَعُوا عَلَى أَنَّ الرَّجُلَ مُبْتَدِعٌ، بَلْ كَافِرٌ وَضَالٌّ كَمَا يَقُولُونَ", "uz": "Ular bu odam bid'atchi, hatto ularning aytishicha, kofir va adashgan degan fikrga kelishdi"}, {"ar": "وَإِنْ كَانَ الْأَمْرُ كَذَلِكَ إِلَّا أَنَّهُ أَفْهَمَهُمْ وَلَمْ يَمْلِكُوا أَمَامَهُ رَدًّا", "uz": "Shunday bo'lsa-da, u ularni yengib qo'ydi, ular unga javob topa olmadilar"}, {"ar": "وَلَمْ يَثْبُتُوا أَمَامَ أَدِلَّتِهِ، فَلَمَّا عَجَزُوا وَضَعُوهُ تَحْتَ السِّيَاطِ", "uz": "va uning dalillari oldida bardosh bera olmadilar; ojiz qolgach, uni qamchi ostiga qo'ydilar"}, {"ar": "حَتَّى يُقِرَّ بِكُرْهٍ بِمَا لَمْ يَسْتَطِيعُوا إِقْنَاعَهُ بِهِ حُجَّةً وَدَلِيلًا", "uz": "toki dalil va hujjat bilan ishontira olmagan narsani majburan tan olsin"}], "full_uz": "Ular bu odam bid'atchi, hatto ularning aytishicha, kofir va yo'ldan ozgan degan fikrga kelishdi. Shunday bo'lsa-da, u ularni yengib qo'ydi, ular unga qarshi javob topa olmadilar va uning dalillari oldida bardosh bera olmadilar. Ojiz qolgach, uni dalil va hujjat bilan ishontira olmagan narsani majburan tan olishi uchun qamchi ostiga qo'ydilar.", "note": null},
{"num": 33, "time": "00:02:43,159 --> 00:03:00,479", "arabic": "رَأَيْتُ ذَلِكَ أَيُّهَا الْمُتَوَكِّلُ، وَهَذَا مَا يُشْعِرُنِي بِالذَّنْبِ تُجَاهَ رَجُلٍ غَلَبَ جُمُوعًا مِمَّنْ يُعَدُّونَ مِنَ الْعُلَمَاءِ، أَخْشَى أَنْ أَكُونَ شَرِيكًا فِي إِثْمٍ لَمْ أَتَبَيَّنْ.", "segs": [{"ar": "رَأَيْتُ ذَلِكَ أَيُّهَا الْمُتَوَكِّلُ،", "uz": "Buni ko'rdim, ey Mutavakkil,"}, {"ar": "وَهَذَا مَا يُشْعِرُنِي بِالذَّنْبِ تُجَاهَ رَجُلٍ", "uz": "va aynan shu narsa olimlardan sanaladigan bir to'da"}, {"ar": "غَلَبَ جُمُوعًا مِمَّنْ يُعَدُّونَ مِنَ الْعُلَمَاءِ،", "uz": "ustidan g'olib kelgan odamga nisbatan meni gunohkor"}, {"ar": "أَخْشَى أَنْ أَكُونَ شَرِيكًا فِي إِثْمٍ لَمْ أَتَبَيَّنْ.", "uz": "his qiladi. Aniq bilmagan bir gunohga sherik bo'lishimdan qo'rqaman."}], "full_uz": "Buni ko'rdim, ey Mutavakkil, va aynan shu narsa olimlardan sanaladigan bir to'da ustidan g'olib kelgan odamga nisbatan meni gunohkor his qiladi. Aniq bilmagan bir gunohga sherik bo'lishimdan qo'rqaman.", "note": null},
{"num": 38, "time": "00:03:00,479 --> 00:03:05,919", "arabic": "غَفَرَ اللَّهُ لَنَا وَلَهُ وَلِلْمُسْلِمِينَ جَمِيعًا يَا أَبِي.", "segs": null, "full_uz": "Alloh bizni, uni va barcha musulmonlarni mag'firat qilsin, ey otajon.", "note": null},
{"num": 39, "time": "00:03:05,919 --> 00:03:08,459", "arabic": "آمِينَ.", "segs": null, "full_uz": "Omin.", "note": null},
{"num": 40, "time": "00:03:08,459 --> 00:03:18,500", "arabic": "أَرْجُو أَنْ لَا يُصِيبَهُ مَكْرُوهٌ، فَأَقَعَ فِي خَطِيئَةٍ أَنْدَمُ عَلَيْهَا، وَأُحَاسَبُ بِسَبَبِهَا أَمَامَ رَبِّي.", "segs": [{"ar": "أَرْجُو أَنْ لَا يُصِيبَهُ مَكْرُوهٌ، فَأَقَعَ فِي خَطِيئَةٍ أَنْدَمُ عَلَيْهَا،", "uz": "Umid qilamanki, unga yomonlik yetmaydi, aks holda men pushaymon bo'ladigan gunohga tushib,"}, {"ar": "وَأُحَاسَبُ بِسَبَبِهَا أَمَامَ رَبِّي.", "uz": "uning sababidan Robbim oldida hisob beraman."}], "full_uz": "Umid qilamanki, unga yomonlik yetmaydi, aks holda men pushaymon bo'ladigan gunohga tushib, uning sababidan Robbim oldida hisob beraman.", "note": null},
{"num": 43, "time": "00:03:18,500 --> 00:03:20,659", "arabic": "لَا تَقْلَقْ يَا مَوْلَايَ.", "segs": null, "full_uz": "Xavotir olmang, xo'jayinim.", "note": null},
{"num": 44, "time": "00:03:20,659 --> 00:03:24,620", "arabic": "سَنَتَتَبَّعُ أَخْبَارَهُ حَتَّى نَتَيَقَّنَ أَنَّهُ مَا زَالَ بِخَيْرٍ.", "segs": null, "full_uz": "Uning ahvolidan xabar topib turamiz, toki u hali ham sog'-omon ekaniga to'liq amin bo'lguncha.", "note": null},
{"num": 45, "time": "00:03:24,620 --> 00:03:30,659", "arabic": "افْعَلْ مَا تَرَاهُ مُنَاسِبًا يَا جَعْفَرُ.", "segs": null, "full_uz": "Munosib deb bilgan narsangni qil, ey Ja'far.", "note": null},
{"num": 46, "time": "00:03:30,659 --> 00:03:33,819", "arabic": "فَالدِّمَاءُ مُحَرَّمَاتٌ يَا بُنَيَّ.", "segs": null, "full_uz": "Zero qonlar harom (daxlsiz)dir, o'g'lim.", "note": null},
{"num": 48, "time": "00:04:15,400 --> 00:04:20,800", "arabic": "حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ.", "segs": null, "full_uz": "Alloh bizga kifoya qiladi, U qanday ham yaxshi vakildir.", "note": "\"حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ\" — Qur'on, Oli Imron surasi, 173-oyat."},
{"num": 50, "time": "00:05:15,399 --> 00:05:17,399", "arabic": "أَمْسِكْ.", "segs": null, "full_uz": "Ushlab tur.", "note": null},
{"num": 51, "time": "00:05:45,399 --> 00:05:57,959", "arabic": "الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ.", "segs": null, "full_uz": "Har qanday holatda ham hamd Allohga xosdir.", "note": null},
{"num": 52, "time": "00:06:07,959 --> 00:06:09,259", "arabic": "السَّلَامُ عَلَيْكُمْ يَا أَبَا بَكْرٍ.", "segs": null, "full_uz": "Assalomu alaykum, ey Abu Bakr.", "note": null},
{"num": 53, "time": "00:06:09,259 --> 00:06:12,099", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ يَا أَبَا نَصْرٍ، يَا أَخَا الْخُزَاعِيِّ.", "segs": [{"ar": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ يَا أَبَا نَصْرٍ،", "uz": "Va alaykum assalomu va rahmatullah, ey Abu Nasr,"}, {"ar": "يَا أَخَا الْخُزَاعِيِّ.", "uz": "ey Xuzoiyning ukasi."}], "full_uz": "Va alaykum assalomu va rahmatullah, ey Abu Nasr, ey Xuzoiyning ukasi.", "note": null},
{"num": 54, "time": "00:06:12,099 --> 00:06:13,039", "arabic": "تَفَضَّلْ تَفَضَّلْ.", "segs": null, "full_uz": "Marhamat, marhamat.", "note": null},
{"num": 55, "time": "00:06:16,199 --> 00:06:23,979", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 57, "time": "00:06:23,979 --> 00:06:30,419", "arabic": "إِنَّ الْإِمَامَ بِخَيْرٍ.", "segs": null, "full_uz": "Imom sog'-omon.", "note": null},
{"num": 58, "time": "00:06:30,419 --> 00:06:35,599", "arabic": "وَيَعْتَذِرُ إِلَيْكُمْ أَنَّ الدَّارَ ضَيِّقَةٌ وَلَنْ تَسَعَكُمْ.", "segs": null, "full_uz": "Uy tor bo'lib, sizlarga yetmasligi uchun sizdan uzr so'raydi.", "note": null},
{"num": 59, "time": "00:06:35,599 --> 00:06:36,399", "arabic": "جَزَاكُمُ اللَّهُ خَيْرًا.", "segs": null, "full_uz": "Alloh sizga yaxshilik bersin.", "note": null},
{"num": 60, "time": "00:06:37,079 --> 00:06:39,120", "arabic": "بِأَبِي أَنْتَ وَأُمِّي يَا أَبَا عَبْدِ اللَّهِ.", "segs": null, "full_uz": "Otam-onam senga fido bo'lsin, ey Abu Abdulloh.", "note": null},
{"num": 61, "time": "00:06:39,120 --> 00:06:46,019", "arabic": "الْحَمْدُ لِلَّهِ الَّذِي ثَبَّتَكَ عَلَى الْحَقِّ، وَنَصَرَكَ عَلَى الْقَوْمِ الظَّالِمِينَ.", "segs": [{"ar": "الْحَمْدُ لِلَّهِ الَّذِي ثَبَّتَكَ عَلَى الْحَقِّ،", "uz": "Seni haq ustida sobit qilgan va zolim qavm"}, {"ar": "وَنَصَرَكَ عَلَى الْقَوْمِ الظَّالِمِينَ.", "uz": "ustidan g'olib qilgan Allohga hamdlar bo'lsin."}], "full_uz": "Seni haq ustida sobit qilgan va zolim qavm ustidan g'olib qilgan Allohga hamdlar bo'lsin.", "note": null},
{"num": 63, "time": "00:06:46,019 --> 00:06:52,519", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا أَبَا نَصْرٍ، وَجَزَاكَ خَيْرًا عَنْ كُلِّ مَا فَعَلْتَ.", "segs": [{"ar": "بَارَكَ اللَّهُ فِيكَ يَا أَبَا نَصْرٍ،", "uz": "Alloh senga barakot bersin, ey Abu Nasr,"}, {"ar": "وَجَزَاكَ خَيْرًا عَنْ كُلِّ مَا فَعَلْتَ.", "uz": "va qilgan barcha ishlaring uchun senga yaxshilik bersin."}], "full_uz": "Alloh senga barakot bersin, ey Abu Nasr, va qilgan barcha ishlaring uchun senga yaxshilik bersin.", "note": null},
{"num": 65, "time": "00:06:52,519 --> 00:07:01,480", "arabic": "لَوْ كُنَّا نَدْرِي أَنَّهُمْ كَانُوا يَجْلِدُونَكَ، لَاقْتَحَمْنَا عَلَيْهِمُ الْقَصْرَ، وَلَوْ كَانَ ثَمَنُ ذَلِكَ رُءُوسَنَا.", "segs": [{"ar": "لَوْ كُنَّا نَدْرِي أَنَّهُمْ كَانُوا يَجْلِدُونَكَ،", "uz": "Agar seni qamchilayotganlarini bilganimizda,"}, {"ar": "لَاقْتَحَمْنَا عَلَيْهِمُ الْقَصْرَ، وَلَوْ كَانَ ثَمَنُ ذَلِكَ رُءُوسَنَا.", "uz": "hatto bunga boshlarimiz to'lov bo'lsa ham, saroyga bostirib kirgan bo'lardik."}], "full_uz": "Agar seni qamchilayotganlarini bilganimizda, hatto bunga boshlarimiz to'lov bo'lsa ham, saroyga bostirib kirgan bo'lardik.", "note": null},
{"num": 68, "time": "00:07:01,480 --> 00:07:05,800", "arabic": "وَلَكِنَّنَا سَمِعْنَا بِالْخَبَرِ بَعْدَ أَنْ قُضِيَ الْأَمْرُ.", "segs": null, "full_uz": "Lekin biz bu xabarni ish tugaganidan keyin eshitdik.", "note": null},
{"num": 69, "time": "00:07:05,800 --> 00:07:08,699", "arabic": "قَدَّرَ اللَّهُ وَمَا شَاءَ فَعَلَ.", "segs": null, "full_uz": "Alloh taqdir qildi va nimani xohlasa, shuni qildi.", "note": null},
{"num": 70, "time": "00:07:08,699 --> 00:07:18,800", "arabic": "الْحَمْدُ لِلَّهِ الَّذِي أَطْفَأَ النَّائِرَةَ بَيْنَ الْخَلِيفَةِ وَرَعَايَاهُ، فَلَمْ تَحْدُثْ فِتْنَةٌ بِسَبَبِي.", "segs": [{"ar": "الْحَمْدُ لِلَّهِ الَّذِي أَطْفَأَ النَّائِرَةَ بَيْنَ الْخَلِيفَةِ وَرَعَايَاهُ،", "uz": "Xalifa bilan uning fuqarolari orasidagi adovat o'tini o'chirgan Allohga hamd bo'lsin,"}, {"ar": "فَلَمْ تَحْدُثْ فِتْنَةٌ بِسَبَبِي.", "uz": "mening sababimdan fitna yuz bermadi."}], "full_uz": "Xalifa bilan uning fuqarolari orasidagi adovat o'tini o'chirgan Allohga hamd bo'lsin, mening sababimdan fitna yuz bermadi.", "note": null},
{"num": 72, "time": "00:07:18,800 --> 00:07:25,360", "arabic": "أَمَا زِلْتَ تَخْشَى الْفِتْنَةَ عَلَيْهِمْ وَلَا تَخْشَاهَا مِنْهُمْ يَا أَبَا عَبْدِ اللَّهِ؟", "segs": [{"ar": "أَمَا زِلْتَ تَخْشَى الْفِتْنَةَ عَلَيْهِمْ", "uz": "Hali ham ular haqida fitnadan qo'rqib,"}, {"ar": "وَلَا تَخْشَاهَا مِنْهُمْ يَا أَبَا عَبْدِ اللَّهِ؟", "uz": "ulardan qo'rqmayapsizmi, ey Abu Abdulloh?"}], "full_uz": "Hali ham ular haqida fitnadan qo'rqib, ulardan qo'rqmayapsizmi, ey Abu Abdulloh?", "note": null},
{"num": 74, "time": "00:07:25,360 --> 00:07:33,699", "arabic": "بَعْضُ الشَّرِّ أَهْوَنُ مِنْ بَعْضٍ أَيُّهَا الْخُزَاعِيُّ.", "segs": null, "full_uz": "Yomonlikning bir turi ikkinchisidan yengilroqdir, ey Xuzoiy.", "note": null},
{"num": 76, "time": "00:07:38,699 --> 00:07:44,420", "arabic": "قَاتَلَهُمُ اللَّهُ، مَا أَشَدَّ سَوَادَ قُلُوبِهِمْ!", "segs": null, "full_uz": "Alloh ularni yo'q qilsin, qalblari naqadar qop-qora ekan!", "note": null},
{"num": 78, "time": "00:07:44,420 --> 00:07:48,959", "arabic": "كَيْفَ طَابَتْ أَنْفُسُهُمْ أَنْ يَصْنَعُوا بِكَ مَا صَنَعُوا؟", "segs": null, "full_uz": "Senga qilgan ishlarini qilishga qanday qilib nafslari toza (rozi) bo'ldi?", "note": null},
{"num": 79, "time": "00:07:48,959 --> 00:07:51,740", "arabic": "هَلَّا دَعَوْتَ عَلَيْهِمْ يَا شَيْخَنَا؟", "segs": null, "full_uz": "Ularga qarshi duo qilsangiz bo'lmasmidi, ey shayximiz?", "note": null},
{"num": 80, "time": "00:07:51,740 --> 00:07:55,879", "arabic": "فَلِلصَّائِمِ وَالْمَظْلُومِ دَعْوَةٌ لَا تُرَدُّ.", "segs": null, "full_uz": "Zero ro'zador va mazlumning duosi qaytarilmaydi.", "note": "Payg'ambar (sav)dan rivoyat qilingan hadisga ishora: mazlum va ro'zadorning duosi qabul bo'lishi haqida."},
{"num": 81, "time": "00:07:55,879 --> 00:08:03,180", "arabic": "كُلُّ مَنْ آذَانِي وَذَكَرَنِي بِسُوءٍ فَهُوَ فِي حِلٍّ، إِلَّا ضَالًّا مُبْتَدِعًا.", "segs": [{"ar": "كُلُّ مَنْ آذَانِي وَذَكَرَنِي بِسُوءٍ فَهُوَ فِي حِلٍّ،", "uz": "Meni ozor bergan va yomon so'zlagan har bir kishini halol qildim,"}, {"ar": "إِلَّا ضَالًّا مُبْتَدِعًا.", "uz": "faqat yo'ldan ozgan bid'atchidan tashqari."}], "full_uz": "Meni ozor bergan va yomon so'zlagan har bir kishini halol qildim, faqat yo'ldan ozgan bid'atchidan tashqari.", "note": null},
{"num": 83, "time": "00:08:03,180 --> 00:08:10,019", "arabic": "غَفَرَ اللَّهُ لَهُمْ جَمِيعًا وَهَدَاهُمْ إِلَى الطَّرِيقِ الْحَقِّ.", "segs": null, "full_uz": "Alloh ularning barchasini mag'firat qilsin va haq yo'lga hidoyat qilsin.", "note": null},
{"num": 84, "time": "00:08:10,019 --> 00:08:16,120", "arabic": "أَتَدْعُو لَهُمْ يَا أَبَا عَبْدِ اللَّهِ بَعْدَ كُلِّ مَا صَنَعُوا؟", "segs": [{"ar": "أَتَدْعُو لَهُمْ يَا أَبَا عَبْدِ اللَّهِ", "uz": "Ularga duo qilyapsizmi, ey Abu Abdulloh,"}, {"ar": "بَعْدَ كُلِّ مَا صَنَعُوا؟", "uz": "qilgan barcha ishlaridan keyin?"}], "full_uz": "Qilgan barcha ishlaridan keyin ularga duo qilyapsizmi, ey Abu Abdulloh?", "note": null},
{"num": 86, "time": "00:08:16,120 --> 00:08:18,180", "arabic": "أَدْعُو عَلَيْهِمْ؟", "segs": null, "full_uz": "Ularga qarshi duo qilaymi?", "note": null},
{"num": 87, "time": "00:08:18,180 --> 00:08:25,100", "arabic": "مَا صَبَرَ مَنْ دَعَا عَلَى ظَالِمِهِ يَا أَبَا نَصْرٍ.", "segs": null, "full_uz": "O'ziga zulm qilganga qarshi duo qilgan kishi sabr qilmagan bo'ladi, ey Abu Nasr.", "note": null},
{"num": 89, "time": "00:08:25,100 --> 00:08:31,800", "arabic": "قَالَ تَعَالَى: إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ.", "segs": null, "full_uz": "Alloh taolo aytadi: \"Albatta sabr qiluvchilarga ajrlari hisobsiz to'liq beriladi.\"", "note": "Qur'on, Zumar surasi, 10-oyat."},
{"num": 91, "time": "00:08:31,800 --> 00:08:42,000", "arabic": "وَقَالَ سُبْحَانَهُ وَتَعَالَى: وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا، فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ.", "segs": [{"ar": "وَقَالَ سُبْحَانَهُ وَتَعَالَى: وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا،", "uz": "Va U pok va oliy zot aytadi: \"Yomonlikning jazosi shunga o'xshash yomonlikdir,"}, {"ar": "فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ.", "uz": "kim afv etib, isloh qilsa, uning ajri Allohga havoladir.\""}], "full_uz": "Va U pok va oliy zot aytadi: \"Yomonlikning jazosi shunga o'xshash yomonlikdir, kim afv etib, isloh qilsa, uning ajri Allohga havoladir.\"", "note": "Qur'on, Shuro surasi, 40-oyat."},
{"num": 94, "time": "00:08:42,000 --> 00:09:00,060", "arabic": "مَا يَنْفَعُنِي أَنْ يُعَذَّبَ اللَّهُ مُسْلِمًا بِسَبَبِ ابْنِ حَنْبَلٍ؟ أَلَمْ تَقُلْ: إِنْ مَاتَ أَحْمَدُ أَوْ قُتِلَ فِي دَارِي، قَالَ النَّاسُ صَبَرَ حَتَّى قُتِلَ، فَاتَّخَذَهُ النَّاسُ إِمَامًا وَثَبَتُوا عَلَى مَا هُمْ عَلَيْهِ.", "segs": [{"ar": "مَا يَنْفَعُنِي أَنْ يُعَذَّبَ اللَّهُ مُسْلِمًا بِسَبَبِ ابْنِ حَنْبَلٍ؟", "uz": "Ibn Hanbal sababli Alloh biror musulmonni azoblasa, menga qanday foyda beradi?"}, {"ar": "أَلَمْ تَقُلْ: إِنْ مَاتَ أَحْمَدُ أَوْ قُتِلَ فِي دَارِي،", "uz": "Sen aytmaganmiding: agar Ahmad o'lsa yoki mening uyimda o'ldirilsa,"}, {"ar": "قَالَ النَّاسُ صَبَرَ حَتَّى قُتِلَ،", "uz": "odamlar \"sabr qilib, o'ldirilguncha chidadi\" deyishadi,"}, {"ar": "فَاتَّخَذَهُ النَّاسُ إِمَامًا وَثَبَتُوا عَلَى مَا هُمْ عَلَيْهِ.", "uz": "natijada uni imom deb qabul qilib, o'z e'tiqodlarida yanada mustahkam bo'lib qolishadi."}], "full_uz": "Ibn Hanbal sababli Alloh biror musulmonni azoblasa, menga qanday foyda beradi? Sen aytmaganmiding: agar Ahmad o'lsa yoki mening uyimda o'ldirilsa, odamlar \"sabr qilib, o'ldirilguncha chidadi\" deyishadi, natijada uni imom deb qabul qilib, o'z e'tiqodlarida yanada mustahkam bo'lib qolishadi?", "note": null},
{"num": 99, "time": "00:09:00,059 --> 00:09:04,179", "arabic": "لَمْ أُنْكِرْ ذَلِكَ يَا مَوْلَايَ.", "segs": null, "full_uz": "Buni inkor etmadim, xo'jayinim.", "note": null},
{"num": 100, "time": "00:09:04,179 --> 00:09:11,539", "arabic": "لَقَدْ رَأَيْتُ أَنَّ خَيْرَ مَا نَفْعَلُهُ هُوَ إِطْلَاقُ سَرَاحِهِ، فَإِنْ مَاتَ خَارِجًا مِنْ عِنْدِنَا شَكَّ النَّاسُ فِي أَمْرِهِ.", "segs": [{"ar": "لَقَدْ رَأَيْتُ أَنَّ خَيْرَ", "uz": "Men eng yaxshi qiladigan ishimiz"}, {"ar": "مَا نَفْعَلُهُ هُوَ إِطْلَاقُ سَرَاحِهِ،", "uz": "uni ozod qilish deb bildim,"}, {"ar": "فَإِنْ مَاتَ خَارِجًا مِنْ عِنْدِنَا شَكَّ النَّاسُ فِي أَمْرِهِ.", "uz": "chunki agar u bizning huzurimizdan chiqib o'lsa, odamlar uning ahvoli haqida shubhaga tushishadi."}], "full_uz": "Men eng yaxshi qiladigan ishimiz uni ozod qilish deb bildim, chunki agar u bizning huzurimizdan chiqib o'lsa, odamlar uning ahvoli haqida shubhaga tushishadi.", "note": null},
{"num": 102, "time": "00:09:11,539 --> 00:09:19,179", "arabic": "فَمِنْهُمْ مَنْ قَالَ أَجَابَ، وَمِنْهُمْ مَنْ قَالَ لَمْ يُجِبْ، فَتَتَمَكَّنُ الْحَيْرَةُ مِنَ النَّاسِ وَتُخَلِّبُهُمْ.", "segs": [{"ar": "فَمِنْهُمْ مَنْ قَالَ أَجَابَ، وَمِنْهُمْ مَنْ قَالَ لَمْ يُجِبْ،", "uz": "Ba'zilar \"javob berdi\" deyishadi, ba'zilar esa \"javob bermadi\" deyishadi,"}, {"ar": "فَتَتَمَكَّنُ الْحَيْرَةُ مِنَ النَّاسِ وَتُخَلِّبُهُمْ.", "uz": "shu bilan odamlar orasida hayronlik hukmron bo'lib, ularni chalg'itadi."}], "full_uz": "Ba'zilar \"javob berdi\" deyishadi, ba'zilar esa \"javob bermadi\" deyishadi, shu bilan odamlar orasida hayronlik hukmron bo'lib, ularni chalg'itadi.", "note": null},
{"num": 104, "time": "00:09:19,179 --> 00:09:23,039", "arabic": "مَاذَا تُرِيدُ أَكْثَرَ مِنْ ذَلِكَ؟", "segs": null, "full_uz": "Bundan ko'ra ko'proq nima xohlaysiz?", "note": null},
{"num": 105, "time": "00:09:23,039 --> 00:09:24,179", "arabic": "مَلِلْتُ الْأَمْرَ بِرُمَّتِهِ.", "segs": null, "full_uz": "Bu ishning bari meni charchatib qo'ydi.", "note": null},
{"num": 106, "time": "00:09:24,179 --> 00:09:32,120", "arabic": "يَا مَوْلَايَ، إِنْ كَانَ قَدْ نَجَا مِنْ بَيْنِ أَيْدِينَا، فَيَجِبُ أَنْ نَمْنَعَهُ أَيَّ هُدًى إِلَى مَجَالِسِ الْعِلْمِ.", "segs": [{"ar": "يَا مَوْلَايَ،", "uz": "Xo'jayinim,"}, {"ar": "إِنْ كَانَ قَدْ نَجَا مِنْ بَيْنِ أَيْدِينَا،", "uz": "agar u qo'limizdan qutulgan bo'lsa ham,"}, {"ar": "فَيَجِبُ أَنْ نَمْنَعَهُ أَيَّ هُدًى إِلَى مَجَالِسِ الْعِلْمِ.", "uz": "uni ilm majlislariga yo'l qo'ymasligimiz kerak."}], "full_uz": "Xo'jayinim, agar u qo'limizdan qutulgan bo'lsa ham, uni ilm majlislariga yo'l qo'ymasligimiz kerak.", "note": null},
{"num": 108, "time": "00:09:32,120 --> 00:09:34,480", "arabic": "كَيْ لَا يَبُثَّ سُمُومَهُ بَيْنَ النَّاسِ.", "segs": null, "full_uz": "Toki zaharini odamlar orasiga tarqatmasin.", "note": null},
{"num": 109, "time": "00:09:34,480 --> 00:09:35,519", "arabic": "اطْمَئِنَّ.", "segs": null, "full_uz": "Xotirjam bo'ling.", "note": null},
{"num": 110, "time": "00:09:35,519 --> 00:09:41,000", "arabic": "صَيَّادُكُمْ سَتُبْقِيهِ أَشْهُرًا فِي مَنْزِلِهِ.", "segs": null, "full_uz": "Sizning ovingiz uni oylab uyida qoldiradi.", "note": null},
{"num": 112, "time": "00:09:41,000 --> 00:09:45,340", "arabic": "وَلَكِنْ يَا مَوْلَايَ، سَمِعْتُ أَنَّ النَّاسَ بَاتُوا يَتَزَاحَمُونَ عَلَى بَابِهِ.", "segs": [{"ar": "وَلَكِنْ يَا مَوْلَايَ،", "uz": "Lekin, xo'jayinim, eshitishimcha,"}, {"ar": "سَمِعْتُ أَنَّ النَّاسَ بَاتُوا يَتَزَاحَمُونَ عَلَى بَابِهِ.", "uz": "odamlar endi uning eshigi oldida bir-biriga tirbandlashib turishibdi."}], "full_uz": "Lekin, xo'jayinim, eshitishimcha, odamlar endi uning eshigi oldida bir-biriga tirbandlashib turishibdi.", "note": null},
{"num": 113, "time": "00:09:45,340 --> 00:09:48,460", "arabic": "بَعْدَ أَنْ أَصْبَحَ بِالنِّسْبَةِ إِلَيْهِمْ بَطَلًا.", "segs": null, "full_uz": "Chunki u ular uchun qahramonga aylanib qoldi.", "note": null},
{"num": 114, "time": "00:09:48,460 --> 00:09:54,320", "arabic": "غَرِيبٌ أَمْرُكُمْ، تَشْغَلُونَ الدَّوْلَةَ بِالْجِدَالِ.", "segs": null, "full_uz": "Sizlarning holingiz g'alati, davlatni bahs-munozara bilan band qilib qo'yyapsizlar.", "note": null},
{"num": 116, "time": "00:09:54,320 --> 00:10:01,720", "arabic": "أَلَيْسَ عِنْدَكُمْ مَا هُوَ أَبْعَدُ مِنَ الْكَلَامِ؟ أَلَا تَهْتَمُّونَ بِقِتَالِ مَنْ ظَهَرَ كُفْرُهُ مِنَ الرُّومِ وَغَيْرِهِمْ؟", "segs": [{"ar": "أَلَيْسَ عِنْدَكُمْ مَا هُوَ أَبْعَدُ مِنَ الْكَلَامِ؟", "uz": "Sizlarda gapdan ko'ra muhimroq ishlar yo'qmi?"}, {"ar": "أَلَا تَهْتَمُّونَ بِقِتَالِ مَنْ ظَهَرَ كُفْرُهُ مِنَ الرُّومِ وَغَيْرِهِمْ؟", "uz": "Kufri oshkor bo'lgan Rum va boshqalarga qarshi kurashish bilan qiziqmaysizlarmi?"}], "full_uz": "Sizlarda gapdan ko'ra muhimroq ishlar yo'qmi? Kufri oshkor bo'lgan Rum va boshqalarga qarshi kurashish bilan qiziqmaysizlarmi?", "note": null},
{"num": 118, "time": "00:10:03,720 --> 00:10:10,720", "arabic": "يَا مَوْلَايَ، إِنَّنَا نَسْتَعِينُ عَلَى قِتَالِ الْكُفْرِ بِإِصْلَاحِ عَقَائِدِ النَّاسِ.", "segs": [{"ar": "يَا مَوْلَايَ،", "uz": "Xo'jayinim,"}, {"ar": "إِنَّنَا نَسْتَعِينُ عَلَى قِتَالِ الْكُفْرِ بِإِصْلَاحِ عَقَائِدِ النَّاسِ.", "uz": "biz kufrga qarshi kurashda odamlarning e'tiqodlarini isloh qilishdan yordam so'raymiz."}], "full_uz": "Xo'jayinim, biz kufrga qarshi kurashda odamlarning e'tiqodlarini isloh qilishdan yordam so'raymiz.", "note": null},
{"num": 120, "time": "00:10:12,720 --> 00:10:18,720", "arabic": "أَلَا يَجْدُرُ بِنَا أَنْ نَكْسِبَ قُلُوبَ الْمُسْلِمِينَ حَتَّى نَتَفَرَّغَ لِقِتَالِ أَعْدَاءِ اللَّهِ؟", "segs": [{"ar": "أَلَا يَجْدُرُ بِنَا أَنْ نَكْسِبَ قُلُوبَ", "uz": "Musulmonlarning qalbini qozonib,"}, {"ar": "الْمُسْلِمِينَ حَتَّى نَتَفَرَّغَ لِقِتَالِ أَعْدَاءِ اللَّهِ؟", "uz": "shundan keyin Allohning dushmanlariga qarshi kurashga bag'ishlanishimiz kerak emasmi?"}], "full_uz": "Musulmonlarning qalbini qozonib, shundan keyin Allohning dushmanlariga qarshi kurashga bag'ishlanishimiz kerak emasmi?", "note": null},
{"num": 122, "time": "00:10:18,720 --> 00:10:24,720", "arabic": "لَا أَنْ نُقَاتِلَ إِخْوَتَنَا لِخِلَافٍ فِي الرَّأْيِ، أَوْ جَرْيًا وَرَاءَ الْهَوَى.", "segs": [{"ar": "لَا أَنْ نُقَاتِلَ إِخْوَتَنَا لِخِلَافٍ فِي الرَّأْيِ،", "uz": "Fikr ixtilofi yoki nafs-havo orqasidan yugurish sababli o'z"}, {"ar": "أَوْ جَرْيًا وَرَاءَ الْهَوَى.", "uz": "birodarlarimizga qarshi kurashmasligimiz kerak."}], "full_uz": "Fikr ixtilofi yoki nafs-havo orqasidan yugurish sababli o'z birodarlarimizga qarshi kurashmasligimiz kerak.", "note": null},
{"num": 125, "time": "00:10:57,720 --> 00:11:01,399", "arabic": "هَا هُوَ السُّحُورُ قَبْلَ أَنْ يَتَبَارَكَ الْأَذَانُ.", "segs": null, "full_uz": "Azon aytilishidan oldin mana sahurlik ovqat tayyor.", "note": null},
{"num": 126, "time": "00:11:01,399 --> 00:11:07,100", "arabic": "أَيْقِظِي صَالِحًا لِيَتَسَحَّرَ.", "segs": null, "full_uz": "Solihni sahurlik uchun uyg'oting.", "note": null},
{"num": 127, "time": "00:11:07,100 --> 00:11:14,300", "arabic": "فَإِنَّ فِي السُّحُورِ بَرَكَةً، كَمَا أَخْبَرَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ.", "segs": [{"ar": "فَإِنَّ فِي السُّحُورِ بَرَكَةً، كَمَا أَخْبَرَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،", "uz": "Payg'ambarimiz (sollallohu alayhi va sallam) xabar berganidek, albatta sahurda barakot bor — unga"}, {"ar": "عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ.", "uz": "salovat va salom bo'lsin."}], "full_uz": "Payg'ambarimiz (sollallohu alayhi va sallam) xabar berganidek, albatta sahurda barakot bor — unga salovat va salom bo'lsin.", "note": "Payg'ambar (sav)ning \"Sahurlik qiling, chunki sahurda barakat bor\" degan hadisiga ishora (Buxoriy, Muslim)."},
{"num": 130, "time": "00:11:27,720 --> 00:11:47,500", "arabic": "الْقُرْآنُ كَلَامُ اللَّهِ غَيْرُ مَخْلُوقٍ.", "segs": null, "full_uz": "Qur'on — Allohning kalomidir, u yaratilgan emas.", "note": null},
{"num": 134, "time": "00:12:57,720 --> 00:13:40,000", "arabic": "أَحْمَدُ بْنُ حَنْبَلٍ، رَجُلٌ هَانَتْ عَلَيْهِ نَفْسُهُ وَكُلُّ مَا يَمْلِكُ فِي سَبِيلِ اللَّهِ، فَنَذَرَهَا لِلَّهِ رَاضِيًا، كَمَا هَانَتْ عَلَى بِلَالٍ نَفْسُهُ، وَإِنَّمَا تَهُونُ أَنْفُسُهُمْ عَلَيْهِمْ.", "segs": [{"ar": "أَحْمَدُ بْنُ حَنْبَلٍ،", "uz": "Ahmad ibn Hanbal —"}, {"ar": "رَجُلٌ هَانَتْ عَلَيْهِ نَفْسُهُ وَكُلُّ مَا يَمْلِكُ فِي سَبِيلِ اللَّهِ،", "uz": "o'zini va egalik qilgan hamma narsasini Alloh yo'lida hech nima deb bilgan,"}, {"ar": "فَنَذَرَهَا لِلَّهِ رَاضِيًا،", "uz": "uni Allohga rozilik bilan nazr qilgan odam,"}, {"ar": "كَمَا هَانَتْ عَلَى بِلَالٍ نَفْسُهُ،", "uz": "xuddi Bilolning o'zini past-hech deb bilgani kabi."}, {"ar": "وَإِنَّمَا تَهُونُ أَنْفُسُهُمْ عَلَيْهِمْ.", "uz": "Ularning o'zlarini hech deb bilishlarining sababi bor."}], "full_uz": "Ahmad ibn Hanbal — o'zini va egalik qilgan hamma narsasini Alloh yo'lida hech nima deb bilgan, uni Allohga rozilik bilan nazr qilgan odam, xuddi Bilolning o'zini past-hech deb bilgani kabi. Ularning o'zlarini hech deb bilishlarining sababi bor.", "note": null},
{"num": 139, "time": "00:13:40,000 --> 00:13:53,879", "arabic": "لِأَنَّهُمْ يَرَوْنَ بِعَيْنِ بَصِيرَتِهِمْ عَاقِبَتَهُمْ فِي الدَّارِ الْآخِرَةِ، أَمَّا عُيُونُ الْأَبْصَارِ فَإِنَّهَا تَنْظُرُ إِلَى الْمَآلِ لَا إِلَى الْحَالِ.", "segs": [{"ar": "لِأَنَّهُمْ يَرَوْنَ بِعَيْنِ بَصِيرَتِهِمْ عَاقِبَتَهُمْ فِي الدَّارِ الْآخِرَةِ،", "uz": "Chunki ular o'z basiratlari ko'zi bilan oxirat diyoridagi oqibatlarini ko'rishadi,"}, {"ar": "أَمَّا عُيُونُ الْأَبْصَارِ", "uz": "ko'z bilan"}, {"ar": "فَإِنَّهَا تَنْظُرُ إِلَى الْمَآلِ لَا إِلَى الْحَالِ.", "uz": "ko'rish esa faqat oqibatga qaraydi, hozirgi holatga emas."}], "full_uz": "Chunki ular o'z basiratlari ko'zi bilan oxirat diyoridagi oqibatlarini ko'rishadi, ko'z bilan ko'rish esa faqat oqibatga qaraydi, hozirgi holatga emas.", "note": null},
{"num": 144, "time": "00:13:53,879 --> 00:14:15,840", "arabic": "وَإِنَّمَا تَكُونُ شِدَّةُ الْبَلَاءِ عَلَى قَدْرِ الدِّينِ، وَقَدْ صَحَّ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: يُبْتَلَى الرَّجُلُ عَلَى حَسَبِ دِينِهِ، فَسُبْحَانَ مَنْ أَيَّدَهُ وَبَصَّرَهُ وَقَوَّاهُ وَنَصَرَهُ.", "segs": [{"ar": "وَإِنَّمَا تَكُونُ شِدَّةُ الْبَلَاءِ عَلَى قَدْرِ الدِّينِ،", "uz": "Sinovning shiddati diniy mustahkamlik darajasiga qarab bo'ladi. Payg'ambar"}, {"ar": "وَقَدْ صَحَّ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ", "uz": "(sollallohu alayhi va sallam)dan sahih rivoyat qilingan: \"Kishi"}, {"ar": "وَسَلَّمَ أَنَّهُ قَالَ: يُبْتَلَى", "uz": "dini darajasiga qarab sinaladi.\" Uni qo'llab-quvvatlagan,"}, {"ar": "الرَّجُلُ عَلَى حَسَبِ دِينِهِ،", "uz": "ko'zini ochgan,"}, {"ar": "فَسُبْحَانَ مَنْ أَيَّدَهُ وَبَصَّرَهُ وَقَوَّاهُ وَنَصَرَهُ.", "uz": "kuchaytirgan va yordam bergan Zot pokdir."}], "full_uz": "Sinovning shiddati diniy mustahkamlik darajasiga qarab bo'ladi. Payg'ambar (sollallohu alayhi va sallam)dan sahih rivoyat qilingan: \"Kishi dini darajasiga qarab sinaladi.\" Uni qo'llab-quvvatlagan, ko'zini ochgan, kuchaytirgan va yordam bergan Zot pokdir.", "note": "\"يُبْتَلَى الرَّجُلُ عَلَى حَسَبِ دِينِهِ\" — Termiziyning hadisiga ishora."},
{"num": 148, "time": "00:14:15,840 --> 00:14:20,620", "arabic": "لَا أَدْرِي يَا ابْنَ مَعِينٍ، لَا أَدْرِي.", "segs": null, "full_uz": "Bilmayman, ey Ibn Ma'in, bilmayman.", "note": null},
{"num": 149, "time": "00:14:20,620 --> 00:14:34,399", "arabic": "وَلَكِنِّي أَحْسِبُ الْإِمَامَ ابْنَ حَنْبَلٍ يَحْمِلُ فِي دَاخِلِهِ غَيْظًا هَادِرًا عَلَى كُلِّ مَنْ زَلَّ مِنَ الْعُلَمَاءِ عَلَى قَوْلِ الْمُعْتَزِلَةِ.", "segs": [{"ar": "وَلَكِنِّي أَحْسِبُ الْإِمَامَ ابْنَ حَنْبَلٍ", "uz": "Lekin men Imom Ibn Hanbal ichida"}, {"ar": "يَحْمِلُ فِي دَاخِلِهِ غَيْظًا هَادِرًا", "uz": "Mu'taziladan chiqqan so'zga moyil bo'lib xato"}, {"ar": "عَلَى كُلِّ مَنْ زَلَّ مِنَ الْعُلَمَاءِ عَلَى قَوْلِ الْمُعْتَزِلَةِ.", "uz": "qilgan har bir olimga qarshi qaynagan g'azab tashiydi deb o'ylayman."}], "full_uz": "Lekin men Imom Ibn Hanbal ichida Mu'taziladan chiqqan so'zga moyil bo'lib xato qilgan har bir olimga qarshi qaynagan g'azab tashiydi deb o'ylayman.", "note": null},
{"num": 152, "time": "00:14:34,399 --> 00:14:43,080", "arabic": "لَقَدْ زَارَهُ بَعْضُ هَؤُلَاءِ الْعُلَمَاءِ، فَلَمْ يَأْبَهْ بِهِمْ وَلَمْ يَسْتَمِعْ إِلَى كَلَامِهِمْ.", "segs": [{"ar": "لَقَدْ زَارَهُ بَعْضُ هَؤُلَاءِ الْعُلَمَاءِ،", "uz": "Bu olimlardan ba'zilari uni ziyorat qilishdi,"}, {"ar": "فَلَمْ يَأْبَهْ بِهِمْ وَلَمْ يَسْتَمِعْ إِلَى كَلَامِهِمْ.", "uz": "lekin u ularga e'tibor bermadi va gaplariga quloq solmadi."}], "full_uz": "Bu olimlardan ba'zilari uni ziyorat qilishdi, lekin u ularga e'tibor bermadi va gaplariga quloq solmadi.", "note": null},
{"num": 154, "time": "00:14:46,220 --> 00:14:48,560", "arabic": "آهِ، إِنِّي ابْنُ مَعِينٍ، آهِ.", "segs": null, "full_uz": "Oh, men Ibn Ma'inman, oh.", "note": null},
{"num": 155, "time": "00:14:48,559 --> 00:14:57,379", "arabic": "مَا الَّذِي يُمْكِنُ أَنْ أَفْعَلَهُ؟ بِأَيِّ وَجْهٍ أَلْقَاهُ بَعْدَ أَنْ تَوَحَّلْتُ فِي هَذِهِ الْفِتْنَةِ؟", "segs": [{"ar": "مَا الَّذِي يُمْكِنُ أَنْ أَفْعَلَهُ؟ بِأَيِّ", "uz": "Nima qila olaman?"}, {"ar": "وَجْهٍ أَلْقَاهُ بَعْدَ أَنْ تَوَحَّلْتُ فِي هَذِهِ الْفِتْنَةِ؟", "uz": "Bu fitnaga botganimdan keyin uni qanday yuz bilan uchrataman?"}], "full_uz": "Nima qila olaman? Bu fitnaga botganimdan keyin uni qanday yuz bilan uchrataman?", "note": null},
{"num": 157, "time": "00:14:57,379 --> 00:15:06,879", "arabic": "يَا ابْنَ مَعِينٍ، أَنْتَ تَعْرِفُ أَبَا عَبْدِ اللَّهِ أَكْثَرَ مِنِّي، فَافْعَلْ مَا تَرَاهُ مُنَاسِبًا، أَنَا لَا أَسْتَطِيعُ أَنْ أَنْصَحَكَ بِشَيْءٍ.", "segs": [{"ar": "يَا ابْنَ مَعِينٍ،", "uz": "Ey Ibn Ma'in,"}, {"ar": "أَنْتَ تَعْرِفُ أَبَا عَبْدِ اللَّهِ أَكْثَرَ مِنِّي،", "uz": "sen Abu Abdullohni mendan yaxshiroq bilasan,"}, {"ar": "فَافْعَلْ مَا تَرَاهُ مُنَاسِبًا،", "uz": "munosib deb bilgan narsangni qil,"}, {"ar": "أَنَا لَا أَسْتَطِيعُ أَنْ أَنْصَحَكَ بِشَيْءٍ.", "uz": "men senga biror narsa maslahat bera olmayman."}], "full_uz": "Ey Ibn Ma'in, sen Abu Abdullohni mendan yaxshiroq bilasan, munosib deb bilgan narsangni qil, men senga biror narsa maslahat bera olmayman.", "note": null},
{"num": 161, "time": "00:15:06,879 --> 00:15:20,299", "arabic": "وَلَكِنِّي لَا أَكْتُمُكَ سِرًّا، لَقَدْ سَمِعْتُ أَنَّ أَبَا عَبْدِ اللَّهِ قَدْ أَقْسَمَ يَمِينًا بِأَنْ لَا يُكَلِّمَ أَحَدًا مِمَّنْ أَجَابَ فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ حَتَّى يَلْقَى وَجْهَ اللَّهِ عَزَّ وَجَلَّ.", "segs": [{"ar": "وَلَكِنِّي لَا أَكْتُمُكَ سِرًّا،", "uz": "Lekin sendan sirni yashirmayman: eshitishimcha,"}, {"ar": "لَقَدْ سَمِعْتُ أَنَّ أَبَا عَبْدِ اللَّهِ قَدْ أَقْسَمَ يَمِينًا بِأَنْ", "uz": "Abu Abdulloh Qur'onning yaratilganligi masalasida (majburan)"}, {"ar": "لَا يُكَلِّمَ أَحَدًا مِمَّنْ أَجَابَ فِي", "uz": "javob bergan hech kim bilan"}, {"ar": "مَسْأَلَةِ خَلْقِ الْقُرْآنِ حَتَّى يَلْقَى", "uz": "Allohning yuzini ko'rguncha gaplashmaslikka"}, {"ar": "وَجْهَ اللَّهِ عَزَّ وَجَلَّ.", "uz": "qasam ichgan."}], "full_uz": "Lekin sendan sirni yashirmayman: eshitishimcha, Abu Abdulloh Qur'onning yaratilganligi masalasida (majburan) javob bergan hech kim bilan Allohning yuzini ko'rguncha gaplashmaslikka qasam ichgan.", "note": null},
{"num": 166, "time": "00:15:20,299 --> 00:15:30,019", "arabic": "سَأَزُورُهُ، سَأَزُورُهُ إِنْ شَاءَ اللَّهُ، وَلْيَكُنْ مَا يَكُونُ.", "segs": null, "full_uz": "Uni ziyorat qilaman, Alloh xohlasa, ziyorat qilaman, nima bo'lsa bo'lsin.", "note": null},
{"num": 169, "time": "00:15:30,019 --> 00:15:32,959", "arabic": "هَذَا شَأْنُكَ، فَافْعَلْ مَا تَشَاءُ.", "segs": null, "full_uz": "Bu sening ishing, xohlaganingni qil.", "note": null},
{"num": 171, "time": "00:15:47,059 --> 00:16:42,059", "arabic": "الْحَمْدُ لِلَّهِ.", "segs": null, "full_uz": "Hamd Allohga xosdir.", "note": null},
{"num": 175, "time": "00:16:47,059 --> 00:16:51,839", "arabic": "لَقَدْ تَعِبْتُ وَسَئِمْتُ.", "segs": null, "full_uz": "Charchadim va toliqdim.", "note": null},
{"num": 176, "time": "00:16:51,839 --> 00:17:13,799", "arabic": "أَنَا أَخْدِمُ فِي حَرَسِ أَمِيرِ الْمُؤْمِنِينَ قُرَابَةَ الْأَرْبَعِينَ عَامًا، وَخُضْتُ حُرُوبًا مُنْذُ خِلَافَةِ أَمِيرِ الْمُؤْمِنِينَ الرَّشِيدِ رَحِمَهُ اللَّهُ، أَظُنُّنِي أَصْبَحْتُ غَيْرَ قَادِرٍ عَلَى الْعَطَاءِ، هَذَا الْعُمْرُ يَكْفِي.", "segs": [{"ar": "أَنَا أَخْدِمُ فِي حَرَسِ أَمِيرِ الْمُؤْمِنِينَ قُرَابَةَ الْأَرْبَعِينَ عَامًا", "uz": "Men mo'minlar amirining qorovulida qariyb qirq yildan beri xizmat qilaman"}, {"ar": "وَخُضْتُ حُرُوبًا مُنْذُ خِلَافَةِ أَمِيرِ الْمُؤْمِنِينَ الرَّشِيدِ رَحِمَهُ اللَّهُ", "uz": "xalifa Rashid (Alloh rahmat qilsin)ning davridan buyon urushlarda qatnashganman"}, {"ar": "أَظُنُّنِي أَصْبَحْتُ غَيْرَ قَادِرٍ عَلَى الْعَطَاءِ، هَذَا الْعُمْرُ يَكْفِي", "uz": "menimcha, endi berishga qodir emasman, bu umr yetarli"}], "full_uz": "Men mo'minlar amirining qorovulida qariyb qirq yildan beri xizmat qilaman, xalifa Rashid (Alloh rahmat qilsin)ning davridan buyon urushlarda qatnashganman. Menimcha, endi berishga qodir emasman, bu umr yetarli.", "note": null},
{"num": 181, "time": "00:17:13,799 --> 00:17:18,079", "arabic": "الْعُمْرُ لَا يُعِيقُ الْمَرْءَ عَنِ الْعَمَلِ يَا أَبَا الْجَحْجَاحِ.", "segs": null, "full_uz": "Yosh insonni ishdan to'xtatmaydi, ey Abu al-Jahjah.", "note": null},
{"num": 182, "time": "00:17:18,079 --> 00:18:10,799", "arabic": "إِنَّ وَرَاءَ الْأُمُورِ مَا وَرَاءَهَا، لَسْنَا مَلَائِكَةً، وَلَا عِصْمَةَ إِلَّا لِلْأَنْبِيَاءِ، نَجْتَهِدُ أَنْ نَكُونَ عَلَى حَقٍّ، رُبَّمَا لَا يُحَالِفُنَا الْحَظُّ دَائِمًا، لَا تُقَاسُ أُمُورُ الْحُكْمِ بِالْأَخْطَاءِ الْعَابِرَةِ، وَلَا بِالْحَوَادِثِ الْفَرِيدَةِ، إِذَا قَرَّرَ كُلُّ قَائِدٍ أَنْ يَتَخَلَّى عَنْ مَنْصِبِهِ مِنْ أَجْلِ خَطَإٍ هُنَا أَوْ هُنَاكَ، لَمْ يَبْقَ أَحَدٌ فِي مَنْصِبِهِ يَوْمًا وَاحِدًا.", "segs": [{"ar": "إِنَّ وَرَاءَ الْأُمُورِ مَا وَرَاءَهَا، لَسْنَا مَلَائِكَةً، وَلَا عِصْمَةَ إِلَّا لِلْأَنْبِيَاءِ", "uz": "Har ishning ortida boshqa sabab bor; biz farishta emasmiz, ismat faqat payg'ambarlarga xos"}, {"ar": "نَجْتَهِدُ أَنْ نَكُونَ عَلَى حَقٍّ، رُبَّمَا لَا يُحَالِفُنَا الْحَظُّ دَائِمًا", "uz": "biz haq ustida bo'lishga harakat qilamiz, ba'zan omad doim yor bo'lmasligi mumkin"}, {"ar": "لَا تُقَاسُ أُمُورُ الْحُكْمِ بِالْأَخْطَاءِ الْعَابِرَةِ، وَلَا بِالْحَوَادِثِ الْفَرِيدَةِ", "uz": "boshqaruv ishlari o'tkinchi xatolar yoki noyob hodisalar bilan o'lchanmaydi"}, {"ar": "إِذَا قَرَّرَ كُلُّ قَائِدٍ أَنْ يَتَخَلَّى عَنْ مَنْصِبِهِ مِنْ أَجْلِ خَطَإٍ هُنَا أَوْ هُنَاكَ، لَمْ يَبْقَ أَحَدٌ فِي مَنْصِبِهِ يَوْمًا وَاحِدًا", "uz": "har bir yo'lboshchi bir xato uchun lavozimidan voz kechsa, hech kim bir kun ham lavozimida qolmagan bo'lardi"}], "full_uz": "Har ishning ortida boshqa bir sabab bor. Biz farishta emasmiz, ismat (gunohsizlik) faqat payg'ambarlarga xosdir. Biz haq ustida bo'lishga harakat qilamiz, ba'zan omad doim bizga yor bo'lmasligi mumkin. Boshqaruv ishlari o'tkinchi xatolar yoki noyob hodisalar bilan o'lchanmaydi. Agar har bir yo'lboshchi bu yerdagi yoki u yerdagi bir xato uchun lavozimidan voz kechishga qaror qilsa, hech kim bir kun ham o'z lavozimida qolmagan bo'lardi.", "note": null},
{"num": 191, "time": "00:18:10,799 --> 00:18:28,940", "arabic": "قَدْ يَكُونُ الْحَقُّ فِيمَا تَقُولُهُ يَا ابْنَ مُصْعَبٍ، لَكِنْ مَاذَا أَمْلِكُ لِنَفْسٍ لَمْ تَعُدْ تَقْوَى عَلَى عَمَلٍ أَلِفَتْهُ فِي السَّابِقِ وَتَسْتَوْحِشُهُ الْآنَ؟", "segs": [{"ar": "قَدْ يَكُونُ الْحَقُّ فِيمَا تَقُولُهُ يَا ابْنَ مُصْعَبٍ،", "uz": "Aytganingda haqiqat bo'lishi mumkin, ey Ibn Mus'ab, lekin ilgari o'rganib qolgan,"}, {"ar": "لَكِنْ مَاذَا أَمْلِكُ لِنَفْسٍ لَمْ تَعُدْ", "uz": "endi esa yot ko'rayotgan bir"}, {"ar": "تَقْوَى عَلَى عَمَلٍ أَلِفَتْهُ فِي السَّابِقِ", "uz": "ishga endi toqat qila olmayotgan nafsim uchun nima qila"}, {"ar": "وَتَسْتَوْحِشُهُ الْآنَ؟", "uz": "olaman?"}], "full_uz": "Aytganingda haqiqat bo'lishi mumkin, ey Ibn Mus'ab, lekin ilgari o'rganib qolgan, endi esa yot ko'rayotgan bir ishga endi toqat qila olmayotgan nafsim uchun nima qila olaman?", "note": null},
{"num": 194, "time": "00:18:28,940 --> 00:18:45,979", "arabic": "كُنْ لَنَا دَائِمًا وَظَاهِرًا أَيُّهَا الْقَائِدُ، كَمَا يَشْهَدُ لَكَ الْبَطَلُ، وَلَكِنْ لَا تَنْقَطِعْ عَنْ زِيَارَتِي، فَبَابِي مَفْتُوحٌ لَكَ دَائِمًا.", "segs": [{"ar": "كُنْ لَنَا دَائِمًا وَظَاهِرًا أَيُّهَا الْقَائِدُ،", "uz": "Doim biz bilan va ko'rinib turing, ey qo'mondon,"}, {"ar": "كَمَا يَشْهَدُ لَكَ الْبَطَلُ، وَلَكِنْ لَا تَنْقَطِعْ عَنْ زِيَارَتِي،", "uz": "mardlik senga guvohlik berayotgandek. Lekin meni ziyorat qilishni to'xtatmang,"}, {"ar": "فَبَابِي مَفْتُوحٌ لَكَ دَائِمًا.", "uz": "mening eshigim senga doim ochiq."}], "full_uz": "Doim biz bilan va ko'rinib turing, ey qo'mondon, mardlik senga guvohlik berayotgandek. Lekin meni ziyorat qilishni to'xtatmang, mening eshigim senga doim ochiq.", "note": null},
{"num": 199, "time": "00:19:39,339 --> 00:19:44,299", "arabic": "بِبَابِكَ يَا أَبَا عَبْدِ اللَّهِ، لَيْتَهُمْ لَا يَفْعَلُونَ ذَلِكَ، يَا ابْنَ حَنْبَلٍ.", "segs": [{"ar": "بِبَابِكَ يَا أَبَا عَبْدِ اللَّهِ،", "uz": "Sizning eshigingiz oldida,"}, {"ar": "لَيْتَهُمْ لَا يَفْعَلُونَ ذَلِكَ، يَا ابْنَ حَنْبَلٍ.", "uz": "ey Abu Abdulloh. Qani edi ular bunday qilmasalar, ey Ibn Hanbal."}], "full_uz": "Sizning eshigingiz oldida, ey Abu Abdulloh. Qani edi ular bunday qilmasalar, ey Ibn Hanbal.", "note": null},
{"num": 202, "time": "00:19:44,299 --> 00:19:57,059", "arabic": "لَا أُرِيدُهُمْ أَنْ يَجْلِسُوا بِبَابِي، إِنَّ ذَلِكَ مَفْسَدَةٌ لِقُلُوبِ الرِّجَالِ، لَيْتَهُمْ يَجْلِسُونَ بِبَابِ اللَّهِ يَسْأَلُونَهُ الثَّبَاتَ عَلَى الْحَقِّ.", "segs": [{"ar": "لَا أُرِيدُهُمْ أَنْ يَجْلِسُوا بِبَابِي،", "uz": "Ularning mening eshigim oldida o'tirishlarini istamayman,"}, {"ar": "إِنَّ ذَلِكَ مَفْسَدَةٌ لِقُلُوبِ الرِّجَالِ،", "uz": "bu erkaklarning qalblari uchun fasoddir. Qani"}, {"ar": "لَيْتَهُمْ يَجْلِسُونَ بِبَابِ اللَّهِ يَسْأَلُونَهُ الثَّبَاتَ عَلَى الْحَقِّ.", "uz": "edi ular Alloh eshigi oldida o'tirib, Undan haq ustida sobitlik so'rasalar."}], "full_uz": "Ularning mening eshigim oldida o'tirishlarini istamayman, bu erkaklarning qalblari uchun fasoddir. Qani edi ular Alloh eshigi oldida o'tirib, Undan haq ustida sobitlik so'rasalar.", "note": null},
{"num": 207, "time": "00:19:57,059 --> 00:20:05,279", "arabic": "إِنَّهُمْ هُنَا لِزِيَارَتِكَ يَا أَحْمَدُ، إِنَّهُمْ مُحِبُّونَ لَكَ.", "segs": null, "full_uz": "Ular bu yerga sizni ziyorat qilish uchun kelishgan, ey Ahmad, ular sizni sevishadi.", "note": null},
{"num": 210, "time": "00:20:05,279 --> 00:20:12,359", "arabic": "فَوَاللَّهِ لَقَدْ تَرَكْتَ بَيْنَهُمْ أَثَرًا فِي حَيَاتِهِمْ، وَقَدْ تَرَكْتَ فَرَاغًا حِينَ ذَهَبْتَ عَنْهُمْ.", "segs": [{"ar": "فَوَاللَّهِ لَقَدْ تَرَكْتَ بَيْنَهُمْ أَثَرًا فِي حَيَاتِهِمْ،", "uz": "Vallohi, siz ularning hayotida iz qoldirdingiz,"}, {"ar": "وَقَدْ تَرَكْتَ فَرَاغًا حِينَ ذَهَبْتَ عَنْهُمْ.", "uz": "va ulardan uzoqlashganingizda bo'shliq qoldirdingiz."}], "full_uz": "Vallohi, siz ularning hayotida iz qoldirdingiz, va ulardan uzoqlashganingizda bo'shliq qoldirdingiz.", "note": null},
{"num": 213, "time": "00:20:12,359 --> 00:20:26,839", "arabic": "وَأَنَا وَاللَّهِ أُكِنُّ لَهُمْ كُلَّ الْحُبِّ، وَلَوْ أَنَّ الْغُرْفَةَ تَتَّسِعُ لَهُمْ جَمِيعًا لَأَدْخَلْتُهُمْ وَاسْتَأْنَسْتُ بِرُؤْيَتِهِمْ.", "segs": [{"ar": "وَأَنَا وَاللَّهِ أُكِنُّ لَهُمْ كُلَّ الْحُبِّ،", "uz": "Men ham, Vallohi, ularga barcha muhabbatni saqlayman,"}, {"ar": "وَلَوْ أَنَّ الْغُرْفَةَ تَتَّسِعُ لَهُمْ جَمِيعًا لَأَدْخَلْتُهُمْ", "uz": "agar xona hammasiga sig'sa edi, ularni ichkariga olib,"}, {"ar": "وَاسْتَأْنَسْتُ بِرُؤْيَتِهِمْ.", "uz": "ko'rishlaridan xursand bo'lardim."}], "full_uz": "Men ham, Vallohi, ularga barcha muhabbatni saqlayman, agar xona hammasiga sig'sa edi, ularni ichkariga olib, ko'rishlaridan xursand bo'lardim.", "note": null},
{"num": 216, "time": "00:20:26,839 --> 00:20:28,960", "arabic": "وَلَيْتَ يَا عَمِّ مَنْ لَمْ يَتَّسِعْ لَهُ الْمَكَانُ أَنْ يَعُودَ فِي وَقْتٍ لَاحِقٍ.", "segs": [{"ar": "وَلَيْتَ يَا عَمِّ مَنْ لَمْ يَتَّسِعْ لَهُ الْمَكَانُ أَنْ يَعُودَ فِي", "uz": "Qani edi, ey amaki, joy yetmagan kishi keyinroq"}, {"ar": "وَقْتٍ لَاحِقٍ.", "uz": "qaytib kelsa."}], "full_uz": "Qani edi, ey amaki, joy yetmagan kishi keyinroq qaytib kelsa.", "note": null},
{"num": 219, "time": "00:20:33,899 --> 00:20:37,879", "arabic": "سَنَتَدَبَّرُ ذَلِكَ لَاحِقًا.", "segs": null, "full_uz": "Buni keyinroq hal qilamiz.", "note": null},
{"num": 220, "time": "00:20:37,880 --> 00:20:41,680", "arabic": "أَحْمَدُ، أَرِحْ نَفْسَكَ فَقَطْ.", "segs": null, "full_uz": "Ahmad, faqat o'zingni dam ol.", "note": null},
{"num": 221, "time": "00:20:41,680 --> 00:20:44,780", "arabic": "اللَّهُ الْمُسْتَعَانُ.", "segs": null, "full_uz": "Yordam faqat Allohdandir.", "note": null},
{"num": 222, "time": "00:20:44,780 --> 00:20:55,880", "arabic": "ابْنُ نَصْرٍ الْخُزَاعِيُّ قَدْ طَغَى كَثِيرًا، وَيَبْدُو أَنَّهُ لَنْ يَتَوَقَّفَ عِنْدَ حَدٍّ إِنْ لَمْ نُوقِفْهُ نَحْنُ.", "segs": [{"ar": "ابْنُ نَصْرٍ الْخُزَاعِيُّ قَدْ طَغَى كَثِيرًا،", "uz": "Ibn Nasr al-Xuzoiy juda oshkora bo'lib ketdi,"}, {"ar": "وَيَبْدُو أَنَّهُ لَنْ يَتَوَقَّفَ عِنْدَ", "uz": "agar biz to'xtatmasak,"}, {"ar": "حَدٍّ إِنْ لَمْ نُوقِفْهُ نَحْنُ.", "uz": "bir chegarada to'xtamaydiganga o'xshaydi."}], "full_uz": "Ibn Nasr al-Xuzoiy juda oshkora bo'lib ketdi, agar biz to'xtatmasak, bir chegarada to'xtamaydiganga o'xshaydi.", "note": null},
{"num": 224, "time": "00:20:56,800 --> 00:21:02,820", "arabic": "لَوْلَاهُ لَكُنَّا ارْتَحْنَا مِنَ ابْنِ حَنْبَلٍ هَذَا وَأَتْبَاعِهِ.", "segs": null, "full_uz": "U bo'lmaganida, bu Ibn Hanbal va uning ergashuvchilaridan qutulgan bo'lardik.", "note": null},
{"num": 225, "time": "00:21:02,819 --> 00:21:09,899", "arabic": "يَجِبُ أَنْ يُعَاقَبَ هَذَا ابْنُ نَصْرٍ الْخُزَاعِيُّ حَتَّى يَرْتَدِعَ.", "segs": null, "full_uz": "Bu Ibn Nasr al-Xuzoiy jazolanishi kerak, toki to'xtasin.", "note": null},
{"num": 226, "time": "00:21:09,899 --> 00:21:17,200", "arabic": "وَكَيْفَ تَقْوَى عَلَيْهِ سَوَاعِدُنَا وَأَنْتُمْ تَعْلَمُونَ مَكَانَةَ أَهْلِهِ مِنْ دَوْلَةِ أَمِيرِ الْمُؤْمِنِينَ؟", "segs": [{"ar": "وَكَيْفَ تَقْوَى عَلَيْهِ سَوَاعِدُنَا", "uz": "Qanday qilib bilaklarimiz unga yetadi,"}, {"ar": "وَأَنْتُمْ تَعْلَمُونَ مَكَانَةَ أَهْلِهِ مِنْ دَوْلَةِ أَمِيرِ الْمُؤْمِنِينَ؟", "uz": "sizlar uning oilasining mo'minlar amiri davlatidagi mavqeyini bilasiz-ku?"}], "full_uz": "Qanday qilib bilaklarimiz unga yetadi, sizlar uning oilasining mo'minlar amiri davlatidagi mavqeyini bilasiz-ku?", "note": null},
{"num": 227, "time": "00:21:17,200 --> 00:21:34,960", "arabic": "لَنْ نَسْتَطِيعَ النَّيْلَ مِنَ الْخُزَاعِيِّ إِلَّا إِذَا أَرْسَلْنَا عَيْنًا مِنْ عُيُونِ إِخْوَتِنَا تُرَاقِبُهُ وَتَأْتِينَا بِأَخْبَارِهِ، ثُمَّ نَتَحَيَّنُ الْفُرْصَةَ، وَسَأَجْعَلُهُ يَدْفَعُ الثَّمَنَ غَالِيًا.", "segs": [{"ar": "لَنْ نَسْتَطِيعَ النَّيْلَ مِنَ الْخُزَاعِيِّ إِلَّا إِذَا أَرْسَلْنَا عَيْنًا مِنْ عُيُونِ إِخْوَتِنَا تُرَاقِبُهُ", "uz": "Xuzoiyga faqat birodarlarimizdan bir josus yuborib, uni kuzatib, xabarlarini bizga keltirsagina zarar yetkaza olamiz,"}, {"ar": "وَتَأْتِينَا بِأَخْبَارِهِ،", "uz": "so'ng fursatni kutamiz,"}, {"ar": "ثُمَّ نَتَحَيَّنُ الْفُرْصَةَ،", "uz": "va men uni"}, {"ar": "وَسَأَجْعَلُهُ يَدْفَعُ الثَّمَنَ غَالِيًا.", "uz": "qimmat narx to'lashga majbur qilaman."}], "full_uz": "Xuzoiyga faqat birodarlarimizdan bir josus yuborib, uni kuzatib, xabarlarini bizga keltirsagina zarar yetkaza olamiz, so'ng fursatni kutamiz, va men uni qimmat narx to'lashga majbur qilaman.", "note": null},
{"num": 231, "time": "00:21:34,960 --> 00:21:39,040", "arabic": "نِعْمَ الرَّأْيُ أَيُّهَا الْأَرْمَنِيُّ، نِعْمَ الرَّأْيُ.", "segs": null, "full_uz": "Qanday ham yaxshi fikr, ey Armaniy, qanday ham yaxshi fikr.", "note": null},
{"num": 232, "time": "00:21:39,040 --> 00:21:47,360", "arabic": "وَلَكِنَّ ذَلِكَ قَدْ يَأْخُذُ وَقْتًا طَوِيلًا، وَلَا بُدَّ أَنْ نُعَوِّضَ هَزِيمَتَنَا بِانْتِصَارٍ مُحَقَّقٍ وَسَرِيعٍ.", "segs": [{"ar": "وَلَكِنَّ ذَلِكَ قَدْ يَأْخُذُ وَقْتًا طَوِيلًا،", "uz": "Lekin bu uzoq vaqt olishi mumkin,"}, {"ar": "وَلَا بُدَّ أَنْ نُعَوِّضَ هَزِيمَتَنَا بِانْتِصَارٍ مُحَقَّقٍ وَسَرِيعٍ.", "uz": "biz mag'lubiyatimizni aniq va tez g'alaba bilan qoplashimiz shart."}], "full_uz": "Lekin bu uzoq vaqt olishi mumkin, biz mag'lubiyatimizni aniq va tez g'alaba bilan qoplashimiz shart.", "note": null},
{"num": 234, "time": "00:21:47,360 --> 00:21:54,840", "arabic": "فَلْيَأْخُذْ مَا أَرَادَ مِنَ الْوَقْتِ، الْمُهِمُّ أَنْ نَتَخَلَّصَ مِنْهُ.", "segs": null, "full_uz": "Xohlagan vaqtini olsin, muhimi undan qutulishimizdir.", "note": null},
{"num": 236, "time": "00:21:58,140 --> 00:22:19,200", "arabic": "تَعَالَ يَا عَلِيُّ، بَارَكَ اللَّهُ فِيكَ يَا وَلَدِي.", "segs": null, "full_uz": "Kel, ey Ali, Alloh senga barakot bersin, o'g'lim.", "note": null},
{"num": 238, "time": "00:22:19,200 --> 00:22:23,600", "arabic": "مَاذَا تَفْعَلُ يَا صَالِحُ؟", "segs": null, "full_uz": "Nima qilyapsan, ey Solih?", "note": null},
{"num": 239, "time": "00:22:23,600 --> 00:22:25,300", "arabic": "أَبِي يُرِيدُ الْخُرُوجَ لِصَلَاةِ الْعِيدِ.", "segs": null, "full_uz": "Otam bayram namoziga chiqmoqchi.", "note": null},
{"num": 240, "time": "00:22:25,300 --> 00:22:35,580", "arabic": "كَيْفَ سَيَخْرُجُ وَقَدْ نَالَ مَا نَالَهُ مِنَ الْجَلْدِ وَالتَّعْذِيبِ؟ إِنَّهُ لَا يَقْوَى عَلَى الْحَرَاكِ دَاخِلَ الدَّارِ حَتَّى يُصَلِّيَ خَارِجَهَا.", "segs": [{"ar": "كَيْفَ سَيَخْرُجُ وَقَدْ نَالَ مَا نَالَهُ مِنَ الْجَلْدِ", "uz": "Qamchilanish va azob-uqubatdan ko'rgan zarari bilan qanday chiqadi?"}, {"ar": "وَالتَّعْذِيبِ؟ إِنَّهُ لَا يَقْوَى عَلَى الْحَرَاكِ", "uz": "U hattoki uy ichida harakat qilishga ham qodir emas,"}, {"ar": "دَاخِلَ الدَّارِ حَتَّى يُصَلِّيَ خَارِجَهَا.", "uz": "tashqarida namoz o'qishga qayerda qodir bo'lsin."}], "full_uz": "Qamchilanish va azob-uqubatdan ko'rgan zarari bilan qanday chiqadi? U hattoki uy ichida harakat qilishga ham qodir emas, tashqarida namoz o'qishga qayerda qodir bo'lsin.", "note": null},
{"num": 243, "time": "00:22:35,580 --> 00:22:39,560", "arabic": "النَّفْسُ هِيَ الَّتِي تَحْمِلُ الْجَسَدَ يَا عَبَّاسَةُ.", "segs": null, "full_uz": "Jismni ko'targan narsa — ruhdir, ey Abbasa.", "note": null},
{"num": 244, "time": "00:22:39,560 --> 00:22:41,440", "arabic": "سَأَتَدَبَّرُ أَمْرًا، لَا تَقْلَقِي.", "segs": null, "full_uz": "Bir chora topaman, xavotir olma.", "note": null},
{"num": 245, "time": "00:22:41,440 --> 00:22:42,900", "arabic": "نَاوِلْنِي يَدَكَ، تَعَالَ يَا أَبِي.", "segs": null, "full_uz": "Qo'lingni ber, kel, dadajon.", "note": null},
{"num": 247, "time": "00:22:42,900 --> 00:22:46,820", "arabic": "لَنْ تَتَدَبَّرَ شَيْئًا، بَلْ سَتَبْقَى حَتَّى تَبْرَأَ تَمَامًا.", "segs": null, "full_uz": "Hech qanday chora ko'rmaysan, aksincha to'liq tuzalguningcha qolasan.", "note": null},
{"num": 249, "time": "00:22:46,820 --> 00:22:54,700", "arabic": "رَأْفَةً بِنَفْسِكَ يَا أَبَا عَبْدِ اللَّهِ.", "segs": null, "full_uz": "O'zingga rahm qil, ey Abu Abdulloh.", "note": null},
{"num": 251, "time": "00:22:54,700 --> 00:22:59,120", "arabic": "أَنَا ذَاهِبٌ لِأُدْرِكَ صَلَاةَ الْعِيدِ وَأُسَلِّمَ عَلَى رِفَاقِي.", "segs": null, "full_uz": "Men bayram namoziga yetib borib, do'stlarimga salom berish uchun ketyapman.", "note": null},
{"num": 252, "time": "00:22:59,120 --> 00:23:00,620", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 253, "time": "00:23:00,620 --> 00:23:01,759", "arabic": "وَعَلَيْكُمُ السَّلَامُ.", "segs": null, "full_uz": "Va alaykum assalom.", "note": null},
{"num": 254, "time": "00:23:01,759 --> 00:23:03,660", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.", "segs": null, "full_uz": "Va alaykum assalomu va rahmatullah.", "note": null},
{"num": 255, "time": "00:23:03,660 --> 00:23:12,019", "arabic": "لَوْ تَرَكْتِنِي أَخْرُجُ يَا عَبَّاسَةُ، فَإِنِّي أَشْعُرُ أَنَّ بِي قُدْرَةً عَلَى الْوُصُولِ إِلَى الْمُصَلَّى.", "segs": [{"ar": "لَوْ تَرَكْتِنِي أَخْرُجُ يَا عَبَّاسَةُ،", "uz": "Meni chiqishga qo'ysang, ey Abbasa,"}, {"ar": "فَإِنِّي أَشْعُرُ أَنَّ بِي قُدْرَةً عَلَى الْوُصُولِ إِلَى الْمُصَلَّى.", "uz": "o'zimda musallaga yetib borishga kuch borday his qilyapman."}], "full_uz": "Meni chiqishga qo'ysang, ey Abbasa, o'zimda musallaga yetib borishga kuch borday his qilyapman.", "note": null},
{"num": 257, "time": "00:23:12,019 --> 00:23:27,399", "arabic": "يَا أَبَا عَبْدِ اللَّهِ، تَعْلَمُ أَنِّي لَمْ أَكُنْ لِأَمْنَعَكَ عَنِ الْخُرُوجِ إِلَى الْمُصَلَّى، لَوْلَا أَنَّكَ مُنْهَكٌ وَلَا تَقْوَى عَلَى الْحَرَاكِ، وَغَفَرَ اللَّهُ لِمَنْ كَانَ سَبَبًا فِي حِرْمَانِي مِنَ الْجُمُعَةِ وَالْجَمَاعَاتِ.", "segs": [{"ar": "يَا أَبَا عَبْدِ اللَّهِ، تَعْلَمُ أَنِّي لَمْ أَكُنْ لِأَمْنَعَكَ عَنِ الْخُرُوجِ إِلَى الْمُصَلَّى،", "uz": "Ey Abu Abdulloh, bilasizki, sizni musallaga chiqishdan man qilmagan bo'lardim,"}, {"ar": "لَوْلَا أَنَّكَ مُنْهَكٌ وَلَا تَقْوَى عَلَى الْحَرَاكِ،", "uz": "agar siz holdan toygan va harakatga qodir bo'lmaganingizda bo'lmasa,"}, {"ar": "وَغَفَرَ اللَّهُ لِمَنْ كَانَ سَبَبًا فِي حِرْمَانِي مِنَ الْجُمُعَةِ وَالْجَمَاعَاتِ.", "uz": "meni juma va jamoatlardan mahrum qilishga sabab bo'lgan kishini Alloh mag'firat qilsin."}], "full_uz": "Ey Abu Abdulloh, bilasizki, agar siz holdan toygan va harakatga qodir bo'lmaganingizda bo'lmasa, sizni musallaga chiqishdan man qilmagan bo'lardim. Meni jума va jamoatlardan mahrum qilishga sabab bo'lgan kishini Alloh mag'firat qilsin.", "note": null},
{"num": 261, "time": "00:23:27,399 --> 00:23:34,539", "arabic": "عِيدًا مُبَارَكًا يَا أَبَا فَوْزٍ، أَعَادَهُ اللَّهُ عَلَيْنَا وَعَلَيْكُمْ بِالْخَيْرِ.", "segs": [{"ar": "عِيدًا مُبَارَكًا يَا أَبَا فَوْزٍ،", "uz": "Bayramingiz muborak bo'lsin, ey Abu Fawz,"}, {"ar": "أَعَادَهُ اللَّهُ عَلَيْنَا وَعَلَيْكُمْ بِالْخَيْرِ.", "uz": "Alloh uni bizga va sizga yaxshilik bilan qaytarsin."}], "full_uz": "Bayramingiz muborak bo'lsin, ey Abu Fawz, Alloh uni bizga va sizga yaxshilik bilan qaytarsin.", "note": null},
{"num": 263, "time": "00:23:34,539 --> 00:23:37,379", "arabic": "كَيْفَ حَالُ أَبِيكَ؟", "segs": null, "full_uz": "Otangizning ahvoli qalay?", "note": null},
{"num": 264, "time": "00:23:37,379 --> 00:23:39,720", "arabic": "بِخَيْرٍ وَالْحَمْدُ لِلَّهِ.", "segs": null, "full_uz": "Yaxshi, alhamdulillah.", "note": null},
{"num": 266, "time": "00:23:51,819 --> 00:23:59,519", "arabic": "بِالْإِذْنِ يَا عُمَرُ، فَلَا نُرِيدُ أَنْ نَتَأَخَّرَ عَنْ أَبِي الْجَحْجَاحِ.", "segs": [{"ar": "بِالْإِذْنِ يَا عُمَرُ،", "uz": "Ruxsat bering,"}, {"ar": "فَلَا نُرِيدُ أَنْ نَتَأَخَّرَ عَنْ أَبِي الْجَحْجَاحِ.", "uz": "ey Umar, Abu al-Jahjahdan kechikishni istamaymiz."}], "full_uz": "Ruxsat bering, ey Umar, Abu al-Jahjahdan kechikishni istamaymiz.", "note": null},
{"num": 268, "time": "00:23:59,519 --> 00:24:01,500", "arabic": "رَافَقَتْكُمُ السَّلَامَةُ.", "segs": null, "full_uz": "Yo'lingiz omon bo'lsin.", "note": null},
{"num": 269, "time": "00:24:21,819 --> 00:24:37,480", "arabic": "لَنْ يَغْفِرَ لِي ابْنُ حَنْبَلٍ مَا فَعَلْتُ، أَنَا عَارِفٌ بِحَزْمِهِ وَصَلَابَةِ رَأْيِهِ.", "segs": [{"ar": "لَنْ يَغْفِرَ لِي ابْنُ حَنْبَلٍ مَا فَعَلْتُ،", "uz": "Ibn Hanbal qilganimni menga kechirmaydi,"}, {"ar": "أَنَا عَارِفٌ بِحَزْمِهِ وَصَلَابَةِ رَأْيِهِ.", "uz": "uning qat'iyati va fikrining qattiqligini bilaman."}], "full_uz": "Ibn Hanbal qilganimni menga kechirmaydi, uning qat'iyati va fikrining qattiqligini bilaman.", "note": null},
{"num": 271, "time": "00:24:37,480 --> 00:24:41,839", "arabic": "وَلَكِنَّهُ غَفَرَ لِجَلَّادِيهِ، فَكَيْفَ لَا يَغْفِرُ لِي؟", "segs": null, "full_uz": "Lekin u jallodlarini kechirdi, menga qanday kechirmasin?", "note": null},
{"num": 272, "time": "00:24:41,839 --> 00:24:46,000", "arabic": "أَيَعْقِلُ أَنَّهُ مَا زَالَ غَاضِبًا مِنِّي؟", "segs": null, "full_uz": "Hali ham mendan g'azablanib turishi mumkinmi?", "note": null},
{"num": 273, "time": "00:24:46,000 --> 00:24:48,879", "arabic": "سَأَدْخُلُ وَلْيَكُنْ مَا يَكُونُ.", "segs": null, "full_uz": "Kiraman, nima bo'lsa bo'lsin.", "note": null},
{"num": 274, "time": "00:24:48,880 --> 00:24:55,160", "arabic": "السَّلَامُ عَلَيْكُمْ يَا أَبَا بَكْرٍ.", "segs": null, "full_uz": "Assalomu alaykum, ey Abu Bakr.", "note": null},
{"num": 275, "time": "00:24:55,160 --> 00:24:56,700", "arabic": "وَعَلَيْكُمُ السَّلَامُ.", "segs": null, "full_uz": "Va alaykum assalom.", "note": null},
{"num": 276, "time": "00:24:56,700 --> 00:24:59,360", "arabic": "أَهْلًا بِإِمَامِنَا يَحْيَى بْنِ مَعِينٍ.", "segs": null, "full_uz": "Imomimiz Yahyo ibn Ma'inga marhabo.", "note": null},
{"num": 277, "time": "00:24:59,360 --> 00:25:02,100", "arabic": "مَا بِكَ؟ قَدْ تَغَيَّرَ وَجْهُكَ.", "segs": null, "full_uz": "Senga nima bo'ldi? Yuzing o'zgarib qolibdi.", "note": null},
{"num": 278, "time": "00:25:02,100 --> 00:25:05,700", "arabic": "لَا لَا، لَا شَيْءَ.", "segs": null, "full_uz": "Yo'q, yo'q, hech gap yo'q.", "note": null},
{"num": 279, "time": "00:25:05,700 --> 00:25:09,000", "arabic": "تَفَضَّلْ تَفَضَّلْ.", "segs": null, "full_uz": "Marhamat, marhamat.", "note": null},
{"num": 281, "time": "00:25:18,880 --> 00:25:37,560", "arabic": "وَحَسِبُوا أَنَّ أَمِيرَ الْمُؤْمِنِينَ الْمُعْتَصِمَ كَانَ أَرْأَفَ الْقَوْمِ بِي أَيُّهَا الْخُزَاعِيُّ، وَلَوْلَا أَنَّ أُولَئِكَ...", "segs": [{"ar": "وَحَسِبُوا أَنَّ أَمِيرَ الْمُؤْمِنِينَ الْمُعْتَصِمَ كَانَ أَرْأَفَ الْقَوْمِ بِي أَيُّهَا الْخُزَاعِيُّ،", "uz": "Ular mo'minlar amiri Mu'tasim menga eng shafqatli odam bo'lgan deb o'ylashdi, ey Xuzoiy,"}, {"ar": "وَلَوْلَا أَنَّ أُولَئِكَ...", "uz": "va agar o'shalar bo'lmaganida..."}], "full_uz": "Ular mo'minlar amiri Mu'tasim menga eng shafqatli odam bo'lgan deb o'ylashdi, ey Xuzoiy, va agar o'shalar bo'lmaganida...", "note": null},
{"num": 284, "time": "00:25:48,880 --> 00:26:02,620", "arabic": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ.", "segs": null, "full_uz": "Assalomu alaykum va rahmatullah.", "note": null},
{"num": 286, "time": "00:26:02,620 --> 00:26:04,360", "arabic": "تَفَضَّلْ يَا أَبَا زَكَرِيَّا.", "segs": null, "full_uz": "Marhamat, ey Abu Zakariyo.", "note": null},
{"num": 287, "time": "00:26:04,360 --> 00:26:10,880", "arabic": "كَيْفَ حَالُكَ يَا أَبَا عَبْدِ اللَّهِ؟", "segs": null, "full_uz": "Ahvolingiz qalay, ey Abu Abdulloh?", "note": null},
{"num": 288, "time": "00:26:18,880 --> 00:26:31,400", "arabic": "أَعْلَمُ أَنَّنَا أَخْطَأْنَا جَمِيعًا يَا أَبَا عَبْدِ اللَّهِ، أَجَلْ، كَانَ عَلَيْنَا أَنْ نَصْبِرَ كَمَا صَبَرْتَ.", "segs": [{"ar": "أَعْلَمُ أَنَّنَا أَخْطَأْنَا جَمِيعًا يَا أَبَا عَبْدِ اللَّهِ،", "uz": "Bilamanki, biz hammamiz xato qildik, ey Abu Abdulloh. Ha,"}, {"ar": "أَجَلْ،", "uz": "siz sabr"}, {"ar": "كَانَ عَلَيْنَا أَنْ نَصْبِرَ كَمَا صَبَرْتَ.", "uz": "qilganingizdek biz ham sabr qilishimiz kerak edi."}], "full_uz": "Bilamanki, biz hammamiz xato qildik, ey Abu Abdulloh. Ha, siz sabr qilganingizdek biz ham sabr qilishimiz kerak edi.", "note": null},
{"num": 290, "time": "00:26:31,400 --> 00:26:37,960", "arabic": "وَلَكِنْ أَكَلَ النَّاسُ لَحْمَ أَحْمَدَ بْنِ حَنْبَلٍ.", "segs": null, "full_uz": "Lekin odamlar Ahmad ibn Hanbalni g'iybat qilib, go'shtini yeb qo'yishdi.", "note": "\"لحم فلان يؤكل\" — birovni g'iybat qilish, uning sha'niga tegish ma'nosidagi ibora."},
{"num": 291, "time": "00:26:37,960 --> 00:26:54,160", "arabic": "إِنْ كَانَ اللَّهُ عَزَّ وَجَلَّ قَدْ رَخَّصَ لَنَا فِي مَوْقِفٍ كَهَذَا أَنْ نَنْطِقَ كَلِمَةَ كُفْرٍ إِنْ نَحْنُ أُكْرِهْنَا، فَلِمَ لَا تَغْفِرُ لَنَا أَنْتَ؟", "segs": [{"ar": "إِنْ كَانَ اللَّهُ عَزَّ وَجَلَّ قَدْ رَخَّصَ لَنَا فِي مَوْقِفٍ كَهَذَا", "uz": "Agar Alloh azza va jalla bunday holatda bizga ruxsat bergan bo'lsa"}, {"ar": "أَنْ نَنْطِقَ كَلِمَةَ كُفْرٍ إِنْ نَحْنُ أُكْرِهْنَا،", "uz": "majbur qilinsak kufr so'zini aytishga,"}, {"ar": "فَلِمَ لَا تَغْفِرُ لَنَا أَنْتَ؟", "uz": "nega o'zingiz bizni kechirmaysiz?"}], "full_uz": "Agar Alloh azza va jalla bunday holatda bizga majbur qilinsak kufr so'zini aytishga ruxsat bergan bo'lsa, nega o'zingiz bizni kechirmaysiz?", "note": null},
{"num": 294, "time": "00:26:54,160 --> 00:27:02,620", "arabic": "أَلَمْ يَقُلْ تَعَالَى: إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ؟", "segs": null, "full_uz": "Alloh taolo aytmaganmidi: \"Magar qalbi imon bilan xotirjam bo'lgan holda majbur qilingan kishi bundan mustasno\"?", "note": "Qur'on, Nahl surasi, 106-oyat."},
{"num": 296, "time": "00:27:02,620 --> 00:27:10,460", "arabic": "أَنَحْنُ أَفْضَلُ أَمْ عَمَّارُ بْنُ يَاسِرٍ رَضِيَ اللَّهُ عَنْهُ؟", "segs": null, "full_uz": "Biz afzalmizmi yoki Ammor ibn Yosir (roziyallohu anhu)mi?", "note": null},
{"num": 298, "time": "00:27:10,460 --> 00:27:52,720", "arabic": "حِينَ أَخَذَهُ الْمُشْرِكُونَ فَلَمْ يَتْرُكُوهُ حَتَّى سَبَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَكَرَ آلِهَتَهُمْ بِخَيْرٍ، فَلَمَّا أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا وَرَاءَكَ؟ قَالَ: شَرٌّ يَا رَسُولَ اللَّهِ، مَا تَرَكْتُ حَتَّى نِلْتَ مِنْكَ وَذَكَرْتُ آلِهَتَهُمْ بِخَيْرٍ، قَالَ: كَيْفَ تَجِدُ قَلْبَكَ؟ قَالَ: مُطْمَئِنٌّ بِالْإِيمَانِ، قَالَ: إِنْ عَادُوا فَعُدْ.", "segs": [{"ar": "حِينَ أَخَذَهُ الْمُشْرِكُونَ فَلَمْ يَتْرُكُوهُ حَتَّى سَبَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَكَرَ آلِهَتَهُمْ بِخَيْرٍ", "uz": "Mushriklar uni ushlab, Payg'ambarni haqorat qilib, butlarini yaxshilik bilan tilga olguncha qo'yib yubormadilar"}, {"ar": "فَلَمَّا أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا وَرَاءَكَ؟", "uz": "Rasulullohga kelganida, U: \"Ne xabar bor?\" dedi"}, {"ar": "قَالَ: شَرٌّ يَا رَسُولَ اللَّهِ، مَا تَرَكْتُ حَتَّى نِلْتَ مِنْكَ وَذَكَرْتُ آلِهَتَهُمْ بِخَيْرٍ", "uz": "U: \"Yomon xabar, sizni haqorat qilib, butlarini yaxshilik bilan tilga olmagunimcha qo'yib yuborishmadi\" dedi"}, {"ar": "قَالَ: كَيْفَ تَجِدُ قَلْبَكَ؟ قَالَ: مُطْمَئِنٌّ بِالْإِيمَانِ، قَالَ: إِنْ عَادُوا فَعُدْ", "uz": "U: \"Qalbing qanday?\" dedi, u: \"Imon bilan xotirjam\" dedi, U: \"Agar qaytarishsa, sen ham qayt\" dedi"}], "full_uz": "Mushriklar uni ushlab, Payg'ambar (sollallohu alayhi va sallam)ni haqorat qilib, ularning butlarini yaxshilik bilan tilga olguncha qo'yib yubormadilar. Rasululloh (sav) huzuriga kelganida: \"Ne xabar bor?\" dedi. U: \"Yomon xabar, ey Rasululloh, sizni haqorat qilib, ularning butlarini yaxshilik bilan tilga olmagunimcha meni qo'yib yuborishmadi\" dedi. U: \"Qalbing qanday holatda?\" dedi. U: \"Imon bilan xotirjam\" dedi. U: \"Agar qaytarishsa, sen ham (shunday) qayt,\" dedi.", "note": "Ammor ibn Yosir (r.a.) haqidagi mashhur rivoyat — mushriklar tomonidan majburlanishi va Rasulullohning javobi haqida."},
{"num": 310, "time": "00:28:09,720 --> 00:28:13,759", "arabic": "حَسَنًا يَا أَبَا عَبْدِ اللَّهِ، كَمَا تَشَاءُ.", "segs": null, "full_uz": "Xo'p, ey Abu Abdulloh, xohlaganingizcha.", "note": null},
{"num": 312, "time": "00:28:13,759 --> 00:28:23,680", "arabic": "رَأَيْتُ مِنْ وَاجِبِي عَلَيْكَ، حَقُّكَ عَلَيَّ، أَنْ أَرَاكَ لِأَطْمَئِنَّ عَلَيْكَ وَتَسْمَعَ مِنِّي.", "segs": [{"ar": "رَأَيْتُ مِنْ وَاجِبِي عَلَيْكَ، حَقُّكَ عَلَيَّ،", "uz": "Sizga bo'lgan burchim, sizning menga bo'lgan haqingiz deb bildimki,"}, {"ar": "أَنْ أَرَاكَ لِأَطْمَئِنَّ عَلَيْكَ وَتَسْمَعَ مِنِّي.", "uz": "ko'rib xotirjam bo'lay va mendan eshiting."}], "full_uz": "Sizga bo'lgan burchim, sizning menga bo'lgan haqingiz deb bildimki, ko'rib xotirjam bo'lay va mendan eshiting.", "note": null},
{"num": 315, "time": "00:28:23,680 --> 00:28:29,339", "arabic": "وَالْحَمْدُ لِلَّهِ رَأَيْتُكَ أَحْسَنَ مِنْ ذِي قَبْلُ.", "segs": null, "full_uz": "Alhamdulillah, sizni avvalgidan yaxshiroq holatda ko'rdim.", "note": null},
{"num": 317, "time": "00:28:29,339 --> 00:28:55,299", "arabic": "عَزِيزٌ عَلَيَّ أَنْ أَرَاكَ مُتَجَافِيًا عَنِّي يَا أَبَا عَبْدِ اللَّهِ، أَحْسِبُ أَنَّ وُقُوفِي أَمَامَكَ هَكَذَا أَصْعَبُ عَلَيَّ مِنْ وُقُوفِي أَمَامَ ابْنِ أَبِي دُؤَادٍ وَجَلْدِهِ.", "segs": [{"ar": "عَزِيزٌ عَلَيَّ أَنْ أَرَاكَ مُتَجَافِيًا عَنِّي يَا أَبَا عَبْدِ اللَّهِ،", "uz": "Sizni mendan yuz o'girgan holda ko'rish menga og'ir,"}, {"ar": "أَحْسِبُ أَنَّ وُقُوفِي أَمَامَكَ هَكَذَا أَصْعَبُ", "uz": "ey Abu Abdulloh. Sizning oldingizda shu tarzda turishim,"}, {"ar": "عَلَيَّ مِنْ وُقُوفِي أَمَامَ ابْنِ أَبِي دُؤَادٍ", "uz": "Ibn Abi Du'od oldida turib qamchilashimdan ham qiyinroq deb"}, {"ar": "وَجَلْدِهِ.", "uz": "o'ylayman."}], "full_uz": "Sizni mendan yuz o'girgan holda ko'rish menga og'ir, ey Abu Abdulloh. Sizning oldingizda shu tarzda turishim, Ibn Abi Du'od oldida turib qamchilashimdan ham qiyinroq deb o'ylayman.", "note": null},
{"num": 320, "time": "00:28:59,339 --> 00:29:14,959", "arabic": "أَنَا لَنْ أَلُومَكَ عَلَى مَا تَفْعَلُ بِهِ يَا رَفِيقَ دَرْبِي، وَلَكِنْ هَذَا وَاجِبٌ عَلَيَّ قَضَيْتُهُ.", "segs": [{"ar": "أَنَا لَنْ أَلُومَكَ عَلَى مَا", "uz": "Men seni qilganing uchun ayblamayman,"}, {"ar": "تَفْعَلُ بِهِ يَا رَفِيقَ دَرْبِي،", "uz": "ey yo'ldoshim,"}, {"ar": "وَلَكِنْ هَذَا وَاجِبٌ عَلَيَّ قَضَيْتُهُ.", "uz": "lekin bu men bajarishim kerak bo'lgan burch edi."}], "full_uz": "Men seni qilganing uchun ayblamayman, ey yo'ldoshim, lekin bu men bajarishim kerak bo'lgan burch edi.", "note": null},
{"num": 324, "time": "00:29:29,339 --> 00:29:44,639", "arabic": "لَقَدْ عَلِمَ الْإِمَامُ مَا فَعَلْتَهُ يَا شُفَيُّ، وَقَدْ سَرَّهُ مَوْقِفُكَ، جَزَاهُ اللَّهُ خَيْرًا.", "segs": [{"ar": "لَقَدْ عَلِمَ الْإِمَامُ مَا فَعَلْتَهُ يَا شُفَيُّ،", "uz": "Imom qilgan ishingizni bilib oldi, ey Shufay,"}, {"ar": "وَقَدْ سَرَّهُ مَوْقِفُكَ، جَزَاهُ اللَّهُ خَيْرًا.", "uz": "va sizning pozitsiyangiz uni xursand qildi, Alloh unga yaxshilik bersin."}], "full_uz": "Imom qilgan ishingizni bilib oldi, ey Shufay, va sizning pozitsiyangiz uni xursand qildi, Alloh unga yaxshilik bersin.", "note": null},
{"num": 327, "time": "00:29:44,639 --> 00:29:50,539", "arabic": "إِنَّمَا فَعَلْتُ ذَلِكَ حَتَّى لَا أَكُونَ مِنَ الظَّالِمِينَ، وَلَا حَتَّى مِنْ أَعْوَانِهِمْ.", "segs": [{"ar": "إِنَّمَا فَعَلْتُ ذَلِكَ حَتَّى لَا أَكُونَ مِنَ الظَّالِمِينَ،", "uz": "Buni faqat zolimlardan bo'lmaslik uchun,"}, {"ar": "وَلَا حَتَّى مِنْ أَعْوَانِهِمْ.", "uz": "hatto ularning yordamchilaridan ham bo'lmaslik uchun qildim."}], "full_uz": "Buni faqat zolimlardan bo'lmaslik uchun, hatto ularning yordamchilaridan ham bo'lmaslik uchun qildim.", "note": null},
{"num": 329, "time": "00:29:50,539 --> 00:29:56,459", "arabic": "وَلَكِنْ يُسْتَغْرَبُ أَنَّكَ إِلَى الْآنَ لَمْ تَزُرْهُ وَلَمْ تَطْمَئِنَّ عَلَى صِحَّتِهِ.", "segs": [{"ar": "وَلَكِنْ يُسْتَغْرَبُ أَنَّكَ إِلَى الْآنَ لَمْ تَزُرْهُ", "uz": "Lekin sizning hozirgacha uni ziyorat qilmaganingiz va"}, {"ar": "وَلَمْ تَطْمَئِنَّ عَلَى صِحَّتِهِ.", "uz": "sog'lig'idan xabar olmaganingiz g'alati."}], "full_uz": "Lekin sizning hozirgacha uni ziyorat qilmaganingiz va sog'lig'idan xabar olmaganingiz g'alati.", "note": null},
{"num": 331, "time": "00:29:56,459 --> 00:30:01,759", "arabic": "لَمْ يَمْنَعْنِي إِلَّا خَجَلِي مِنْهُ، أَوَلَسْتُ أَنِّي كُنْتُ سَجَّانَهُ وَشَارَكْتُ فِي ظُلْمِهِ؟", "segs": [{"ar": "لَمْ يَمْنَعْنِي إِلَّا خَجَلِي مِنْهُ،", "uz": "Meni faqat undan uyalganim to'sdi."}, {"ar": "أَوَلَسْتُ أَنِّي كُنْتُ سَجَّانَهُ وَشَارَكْتُ فِي ظُلْمِهِ؟", "uz": "Men uning qamoqchisi bo'lib, zulmiga sherik bo'lmaganmidim?"}], "full_uz": "Meni faqat undan uyalganim to'sdi. Men uning qamoqchisi bo'lib, zulmiga sherik bo'lmaganmidim?", "note": null},
{"num": 334, "time": "00:30:01,759 --> 00:30:07,539", "arabic": "مَنْ تَابَ تَابَ اللَّهُ عَلَيْهِ يَا أَبَا الْجَحْجَاحِ.", "segs": null, "full_uz": "Kim tavba qilsa, Alloh uning tavbasini qabul qiladi, ey Abu al-Jahjah.", "note": null},
{"num": 336, "time": "00:30:07,539 --> 00:30:15,359", "arabic": "ثُمَّ إِنَّكَ لَمْ تَأْلُ جَهْدًا فِي نُصْرَةِ الْإِمَامِ، مَا رَأْيُكَ أَنْ تَزُورَهُ لِتَهْدَأَ النُّفُوسُ وَتَصْفُوَ الْقُلُوبُ؟", "segs": [{"ar": "ثُمَّ إِنَّكَ لَمْ تَأْلُ جَهْدًا فِي نُصْرَةِ الْإِمَامِ،", "uz": "Bundan tashqari, siz imomga yordam berishda hech qanday kuch ayamadingiz,"}, {"ar": "مَا رَأْيُكَ أَنْ تَزُورَهُ لِتَهْدَأَ النُّفُوسُ وَتَصْفُوَ الْقُلُوبُ؟", "uz": "nazaringizda, u bilan ko'rishib, ko'ngillar tinchlanib, qalblar tozalansa qandaydir?"}], "full_uz": "Bundan tashqari, siz imomga yordam berishda hech qanday kuch ayamadingiz. Nazaringizda, u bilan ko'rishib, ko'ngillar tinchlanib, qalblar tozalansa qandaydir?", "note": null},
{"num": 339, "time": "00:30:15,359 --> 00:30:24,620", "arabic": "مَاذَا قُلْتَ؟ سَأَرَى، سَأُفَكِّرُ فِي الْأَمْرِ.", "segs": null, "full_uz": "Nima dedingiz? Ko'raman, bu haqda o'ylab ko'raman.", "note": null},
{"num": 342, "time": "00:30:24,620 --> 00:30:28,900", "arabic": "حَسَنًا، إِذَنْ لِي.", "segs": null, "full_uz": "Xo'p, unda ijozat bering.", "note": null},
{"num": 344, "time": "00:30:28,900 --> 00:30:30,299", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 345, "time": "00:30:30,299 --> 00:30:32,900", "arabic": "وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.", "segs": null, "full_uz": "Va alayka assalomu va rahmatullohi va barakatuh.", "note": null},
{"num": 346, "time": "00:30:32,900 --> 00:30:58,740", "arabic": "كَأَنَّكَ قَسَوْتَ عَلَى أَبِي زَكَرِيَّا يَا أَبَا عَبْدِ اللَّهِ.", "segs": null, "full_uz": "Go'yo Abu Zakariyoga qattiqqo'llik qilgandaysiz, ey Abu Abdulloh.", "note": null},
{"num": 347, "time": "00:31:00,740 --> 00:31:05,579", "arabic": "غَفَرَ اللَّهُ لَنَا وَلَهُ، يَغْفِرُ اللَّهُ لَنَا جَمِيعًا.", "segs": null, "full_uz": "Alloh bizni va uni mag'firat qilsin, Alloh hammamizni mag'firat qiladi.", "note": null},
{"num": 349, "time": "00:31:05,579 --> 00:31:16,559", "arabic": "وَلَكِنْ مَا فَعَلَهُ ابْنُ مَعِينٍ وَغَيْرُهُ مِنْ عُلَمَاءِ بَغْدَادَ، خَطِيئَةٌ يَجِبُ أَنْ يَبْقَوْا مُسْتَغْفِرِينَ اللَّهَ عَلَيْهَا إِلَى آخِرِ حَيَاتِهِمْ.", "segs": [{"ar": "وَلَكِنْ مَا فَعَلَهُ ابْنُ مَعِينٍ وَغَيْرُهُ مِنْ عُلَمَاءِ بَغْدَادَ،", "uz": "Lekin Ibn Ma'in va Bag'dodning boshqa olimlari qilgan ish"}, {"ar": "خَطِيئَةٌ يَجِبُ أَنْ يَبْقَوْا مُسْتَغْفِرِينَ", "uz": "— umrlarining oxirigacha Allohdan mag'firat"}, {"ar": "اللَّهَ عَلَيْهَا إِلَى آخِرِ حَيَاتِهِمْ.", "uz": "so'rab yurishlari lozim bo'lgan xatodir."}], "full_uz": "Lekin Ibn Ma'in va Bag'dodning boshqa olimlari qilgan ish — umrlarining oxirigacha Allohdan mag'firat so'rab yurishlari lozim bo'lgan xatodir.", "note": null},
{"num": 351, "time": "00:31:16,559 --> 00:31:19,220", "arabic": "إِنَّهُمْ عُلَمَاءُ الْأُمَّةِ.", "segs": null, "full_uz": "Ular ummatning olimlaridir.", "note": null},
{"num": 352, "time": "00:31:19,220 --> 00:31:37,519", "arabic": "وَحِينَ يَبْحَثُ عُلَمَاءُ الْأُمَّةِ عَنِ الرُّخَصِ، إِنْ كَانَ لَهُمْ فِي ذَلِكَ رُخْصَةٌ، فَإِنَّهُمْ يُبَلْبِلُونَ أَفْكَارَ النَّاسِ وَعَقَائِدَهُمْ، فَعُيُونُ النَّاسِ مَعْقُودَةٌ عَلَيْهِمْ، وَقَدْ أَوْشَكُوا أَنْ يَسُوقُوا الْكَثِيرَ مِنَ الْعَوَامِّ خَلْفَهُمْ بِفِعْلَتِهِمُ الشَّنْعَاءِ تِلْكَ.", "segs": [{"ar": "وَحِينَ يَبْحَثُ عُلَمَاءُ الْأُمَّةِ عَنِ الرُّخَصِ، إِنْ كَانَ لَهُمْ فِي ذَلِكَ رُخْصَةٌ", "uz": "Ummat olimlari ruxsatlar izlab yurgan vaqtda, hatto ularga bunday ruxsat bo'lsa ham"}, {"ar": "فَإِنَّهُمْ يُبَلْبِلُونَ أَفْكَارَ النَّاسِ وَعَقَائِدَهُمْ، فَعُيُونُ النَّاسِ مَعْقُودَةٌ عَلَيْهِمْ", "uz": "bu odamlarning fikri va e'tiqodini chalkashtiradi, chunki odamlarning ko'zi ularga qadalgan"}, {"ar": "وَقَدْ أَوْشَكُوا أَنْ يَسُوقُوا الْكَثِيرَ مِنَ الْعَوَامِّ خَلْفَهُمْ بِفِعْلَتِهِمُ الشَّنْعَاءِ تِلْكَ", "uz": "ular o'sha qabih ishi bilan omma xalqning ko'pini o'z ortidan ergashtirib olishga yaqinlashdilar"}], "full_uz": "Ummat olimlari ruxsatlar izlab yurgan vaqtda, hatto ularga bunday ruxsat bo'lsa ham, bu odamlarning fikri va e'tiqodini chalkashtirib yuboradi. Chunki odamlarning ko'zi ularga qadalgan, va ular o'zlarining bu qabih ishi bilan omma xalqning ko'pini o'z ortidan ergashtirib olishga yaqinlashdilar.", "note": null},
{"num": 358, "time": "00:31:37,519 --> 00:31:44,559", "arabic": "وَلَكِنْ يَا إِمَامُ، مَا دَامَ لَهُمْ رُخْصَةٌ فِي ذَلِكَ، فَلِمَ نُحَمِّلُهُمْ فَوْقَ طَاقَتِهِمْ؟", "segs": [{"ar": "وَلَكِنْ يَا إِمَامُ، مَا دَامَ لَهُمْ رُخْصَةٌ فِي ذَلِكَ،", "uz": "Lekin, ey Imom, ularga bu borada ruxsat bo'lgan ekan,"}, {"ar": "فَلِمَ نُحَمِّلُهُمْ فَوْقَ طَاقَتِهِمْ؟", "uz": "nega ularga toqatlaridan ortiqchasini yuklaymiz?"}], "full_uz": "Lekin, ey Imom, ularga bu borada ruxsat bo'lgan ekan, nega ularga toqatlaridan ortiqchasini yuklaymiz?", "note": null},
{"num": 361, "time": "00:31:44,559 --> 00:31:50,940", "arabic": "أَجَلْ يَا إِمَامُ، قُلُوبُ الْعِبَادِ كَمَا تَعْلَمُ عَلَى تَفَاوُتٍ، وَقُوَّتُهُمْ عَلَى اخْتِلَافٍ وَتَبَايُنٍ.", "segs": [{"ar": "أَجَلْ يَا إِمَامُ، قُلُوبُ الْعِبَادِ كَمَا تَعْلَمُ عَلَى تَفَاوُتٍ،", "uz": "Ha, ey Imom, bilasizki, bandalarning qalblari turlicha,"}, {"ar": "وَقُوَّتُهُمْ عَلَى اخْتِلَافٍ وَتَبَايُنٍ.", "uz": "kuchlari ham har xil va bir-biridan farqli."}], "full_uz": "Ha, ey Imom, bilasizki, bandalarning qalblari turlicha, kuchlari ham har xil va bir-biridan farqli.", "note": null},
{"num": 364, "time": "00:31:50,940 --> 00:31:53,940", "arabic": "عَنْ أَيِّ رُخْصَةٍ تَتَحَدَّثُونَ؟", "segs": null, "full_uz": "Qanday ruxsat haqida gapiryapsizlar?", "note": null},
{"num": 365, "time": "00:31:54,759 --> 00:32:19,279", "arabic": "إِنَّهُمْ يَتَأَوَّلُونَ حَدِيثَ عَمَّارِ بْنِ يَاسِرٍ رَضِيَ اللَّهُ عَنْهُ عَلَى غَيْرِ وَجْهِهِ، أَلَا فَلْيَعْلَمُوا أَنَّ عَمَّارَ بْنَ يَاسِرٍ رَضِيَ اللَّهُ عَنْهُ لَمْ يَنْطِقْ كَلِمَةَ الْكُفْرِ حَتَّى آذَاهُ الْمُشْرِكُونَ وَضَرَبُوهُ، أَمَّا عُلَمَاؤُنَا فَقَدْ نَطَقُوا كَلِمَةَ الْكُفْرِ وَهُمْ فِي سَعَةٍ وَرَاحَةٍ، وَكُؤُوسُ الْمَاءِ تَدُورُ بَيْنَ شِفَاهِهِمْ.", "segs": [{"ar": "إِنَّهُمْ يَتَأَوَّلُونَ حَدِيثَ عَمَّارِ بْنِ يَاسِرٍ رَضِيَ اللَّهُ عَنْهُ عَلَى غَيْرِ وَجْهِهِ", "uz": "Ular Ammor ibn Yosirning hadisini o'z o'rnida bo'lmagan tarzda talqin qilishyapti"}, {"ar": "أَلَا فَلْيَعْلَمُوا أَنَّ عَمَّارَ بْنَ يَاسِرٍ رَضِيَ اللَّهُ عَنْهُ لَمْ يَنْطِقْ كَلِمَةَ الْكُفْرِ حَتَّى آذَاهُ الْمُشْرِكُونَ وَضَرَبُوهُ", "uz": "Bilishsinki, Ammor mushriklar ozorlab urishmaguncha kufr so'zini aytmagan edi"}, {"ar": "أَمَّا عُلَمَاؤُنَا فَقَدْ نَطَقُوا كَلِمَةَ الْكُفْرِ وَهُمْ فِي سَعَةٍ وَرَاحَةٍ، وَكُؤُوسُ الْمَاءِ تَدُورُ بَيْنَ شِفَاهِهِمْ", "uz": "bizning olimlarimiz esa keng-rohatda, suv kosalari aylanib turgan holda kufr so'zini aytishdi"}], "full_uz": "Ular Ammor ibn Yosir (r.a.)ning hadisini o'z o'rnida bo'lmagan tarzda talqin qilishyapti. Bilib qo'yishsinki, Ammor ibn Yosir (r.a.) mushriklar uni ozorlab, urishmaguncha kufr so'zini aytmagan edi. Bizning olimlarimiz esa keng-mo'l va rohatda turib, suv kosalari lablari orasida aylanib turgan holda kufr so'zini aytishdi.", "note": null},
{"num": 371, "time": "00:32:19,279 --> 00:32:33,379", "arabic": "أَلَا فَلْتَعْلَمُوا أَنَّ الْعُلَمَاءَ هُمْ سَدُّ الدِّفَاعِ الْأَوَّلِ عَنِ الْإِسْلَامِ، وَلَوْ كَانَ ابْنُ مَعِينٍ وَمَنْ مَعَهُ صَبَرُوا وَقَامُوا لِلَّهِ، لَكَانَ الْأَمْرُ قَدِ انْقَطَعَ وَانْتَهَتِ الْفِتْنَةُ.", "segs": [{"ar": "أَلَا", "uz": "Bilib qo'yingki,"}, {"ar": "فَلْتَعْلَمُوا أَنَّ الْعُلَمَاءَ هُمْ", "uz": "olimlar Islomni himoya"}, {"ar": "سَدُّ الدِّفَاعِ الْأَوَّلِ عَنِ الْإِسْلَامِ،", "uz": "qiluvchi birinchi to'g'ondir. Agar Ibn Ma'in"}, {"ar": "وَلَوْ كَانَ ابْنُ مَعِينٍ وَمَنْ مَعَهُ صَبَرُوا وَقَامُوا لِلَّهِ،", "uz": "va u bilan birga bo'lganlar sabr qilib, Alloh uchun turganlarida edi,"}, {"ar": "لَكَانَ الْأَمْرُ قَدِ انْقَطَعَ وَانْتَهَتِ الْفِتْنَةُ.", "uz": "bu ish tugab, fitna to'xtagan bo'lardi."}], "full_uz": "Bilib qo'yingki, olimlar Islomni himoya qiluvchi birinchi to'g'ondir. Agar Ibn Ma'in va u bilan birga bo'lganlar sabr qilib, Alloh uchun turganlarida edi, bu ish tugab, fitna to'xtagan bo'lardi.", "note": null},
{"num": 374, "time": "00:32:33,379 --> 00:32:43,119", "arabic": "أَلَمْ يَتَفَكَّرُوا فِي أَمْرِ مُحَمَّدِ بْنِ نُوحٍ رَحِمَهُ اللَّهُ، الَّذِي صَبَرَ وَقَامَ بِأَمْرٍ لَا يُطِيقُ الْقِيَامَ بِهِ غَيْرُهُ؟", "segs": [{"ar": "أَلَمْ يَتَفَكَّرُوا فِي أَمْرِ مُحَمَّدِ بْنِ نُوحٍ رَحِمَهُ اللَّهُ،", "uz": "Muhammad ibn Nuh (Alloh unga rahmat qilsin) haqida o'ylab ko'rishmadimi,"}, {"ar": "الَّذِي صَبَرَ وَقَامَ بِأَمْرٍ لَا يُطِيقُ الْقِيَامَ بِهِ غَيْرُهُ؟", "uz": "sabr qilib, boshqa hech kim ko'tara olmaydigan ishni ko'targan edi?"}], "full_uz": "Sabr qilib, boshqa hech kim ko'tara olmaydigan ishni ko'targan Muhammad ibn Nuh (Alloh unga rahmat qilsin) haqida o'ylab ko'rishmadimi?", "note": null},
{"num": 376, "time": "00:32:43,119 --> 00:32:48,259", "arabic": "رَحِمَ اللَّهُ ابْنَ نُوحٍ، رَحْمَةُ اللَّهِ عَلَيْهِ.", "segs": null, "full_uz": "Alloh Ibn Nuhga rahmat qilsin, Allohning rahmati unga bo'lsin.", "note": null},
{"num": 378, "time": "00:32:48,259 --> 00:32:59,199", "arabic": "عَزِيزٌ عَلَيَّ أَنْ تُذِيبَ الدُّنْيَا أَكْبَادَ رِجَالٍ وَعَى صُدُورُهُمُ الْقُرْآنَ.", "segs": [{"ar": "عَزِيزٌ عَلَيَّ أَنْ تُذِيبَ الدُّنْيَا أَكْبَادَ رِجَالٍ", "uz": "Ko'ksida Qur'onni saqlagan erlarning jigarlarini dunyo eritib yuborishi"}, {"ar": "وَعَى صُدُورُهُمُ الْقُرْآنَ.", "uz": "menga og'ir keladi."}], "full_uz": "Ko'ksida Qur'onni saqlagan erlarning jigarlarini dunyo eritib yuborishi menga og'ir keladi.", "note": null},
{"num": 380, "time": "00:33:00,099 --> 00:33:16,500", "arabic": "أَرَادَ النَّاسُ مِنَّا أَنْ نَكُونَ مِثْلَ أَحْمَدَ بْنِ حَنْبَلٍ، وَاللَّهِ مَا نَقْوَى أَنْ نَكُونَ مِثْلَهُ، وَلَمْ نُطِقْ سُلُوكَ طَرِيقِهِ.", "segs": [{"ar": "أَرَادَ النَّاسُ مِنَّا أَنْ نَكُونَ مِثْلَ أَحْمَدَ بْنِ حَنْبَلٍ،", "uz": "Odamlar bizdan Ahmad ibn Hanbalga o'xshash bo'lishimizni istashdi. Vallohi,"}, {"ar": "وَاللَّهِ مَا نَقْوَى أَنْ نَكُونَ مِثْلَهُ،", "uz": "biz unga o'xshay olmaymiz va uning"}, {"ar": "وَلَمْ نُطِقْ سُلُوكَ طَرِيقِهِ.", "uz": "yo'lidan yura olmadik."}], "full_uz": "Odamlar bizdan Ahmad ibn Hanbalga o'xshash bo'lishimizni istashdi. Vallohi, biz unga o'xshay olmaymiz va uning yo'lidan yura olmadik.", "note": null},
{"num": 383, "time": "00:33:16,500 --> 00:33:22,599", "arabic": "رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا.", "segs": [{"ar": "رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ", "uz": "Robbimiz, bizga toqatimiz yetmaydigan narsani yuklama va bizni"}, {"ar": "وَاعْفُ عَنَّا.", "uz": "afv et."}], "full_uz": "Robbimiz, bizga toqatimiz yetmaydigan narsani yuklama va bizni afv et.", "note": "Qur'on, Baqara surasi, 286-oyat."},
{"num": 385, "time": "00:33:31,099 --> 00:33:37,099", "arabic": "أَيُّهَا النَّاسُ، أَيُّهَا النَّاسُ، عُودُوا إِلَى بُيُوتِكُمْ يَرْحَمْكُمُ اللَّهُ.", "segs": null, "full_uz": "Ey odamlar, ey odamlar, uylaringizga qaytinglar, Alloh sizlarga rahm qilsin.", "note": null},
{"num": 388, "time": "00:33:38,099 --> 00:33:39,099", "arabic": "فَإِمَامُكُمْ بِخَيْرٍ.", "segs": null, "full_uz": "Imomingiz sog'-omon.", "note": null},
{"num": 389, "time": "00:33:40,099 --> 00:33:41,099", "arabic": "هَيَّا أَيُّهَا النَّاسُ هَيَّا.", "segs": null, "full_uz": "Yuring, ey odamlar, yuring.", "note": null},
{"num": 390, "time": "00:33:51,099 --> 00:33:54,099", "arabic": "لَقَدْ وَجَدْتُ الرَّجُلَ الَّذِي سَيَقُومُ بِالْمُهِمَّةِ الَّتِي اتَّفَقْنَا عَلَيْهَا.", "segs": null, "full_uz": "Kelishgan vazifamizni bajaradigan odamni topdim.", "note": null},
{"num": 391, "time": "00:33:57,099 --> 00:33:58,099", "arabic": "أَيُّ مُهِمَّةٍ؟", "segs": null, "full_uz": "Qaysi vazifa?", "note": null},
{"num": 392, "time": "00:33:58,099 --> 00:34:00,799", "arabic": "أَنَسِيتَ؟", "segs": null, "full_uz": "Unutdingmi?", "note": null},
{"num": 393, "time": "00:34:00,799 --> 00:34:03,480", "arabic": "مُرَاقَبَةُ أَحْمَدَ بْنِ نَصْرٍ الْخُزَاعِيِّ.", "segs": null, "full_uz": "Ahmad ibn Nasr al-Xuzoiyni kuzatib borish.", "note": null},
{"num": 394, "time": "00:34:03,480 --> 00:34:09,799", "arabic": "وَمَنْ يَكُونُ هَذَا الرَّجُلُ؟", "segs": null, "full_uz": "Bu odam kim bo'ladi?", "note": null},
{"num": 395, "time": "00:34:09,799 --> 00:34:11,279", "arabic": "إِنَّهُ طَالِبُ بْنُ السِّرَاجِ.", "segs": null, "full_uz": "U Tolib ibn as-Siroj.", "note": null},
{"num": 396, "time": "00:34:11,279 --> 00:34:17,460", "arabic": "شَابٌّ تَقِيٌّ وَقَدْ طَلَبَ الْعِلْمَ صَغِيرًا، وَهُوَ عَلَى مَا نَحْنُ عَلَيْهِ مِنَ الْحَقِّ.", "segs": [{"ar": "شَابٌّ تَقِيٌّ وَقَدْ طَلَبَ الْعِلْمَ صَغِيرًا،", "uz": "Taqvodor yigit, yoshligidan ilm talab qilgan,"}, {"ar": "وَهُوَ عَلَى مَا نَحْنُ عَلَيْهِ مِنَ الْحَقِّ.", "uz": "va u bizning haqimiz ustida."}], "full_uz": "Taqvodor yigit, yoshligidan ilm talab qilgan, va u bizning haqimiz ustida.", "note": null},
{"num": 398, "time": "00:34:17,460 --> 00:34:21,519", "arabic": "وَسَيَكُونُ أَنْسَبَ مَنْ نَدُسُّهُ فِي جَمَاعَةِ ابْنِ نَصْرٍ.", "segs": null, "full_uz": "U Ibn Nasr jamoasiga kiritishga eng mos kishi bo'ladi.", "note": null},
{"num": 399, "time": "00:34:21,519 --> 00:34:30,579", "arabic": "فَهُمْ يَدَّعُونَ أَنَّهُمْ رِجَالُ الْحَدِيثِ، وَابْنُ سِرَاجٍ لَدَيْهِ مَعْرِفَةٌ وَاسِعَةٌ بِهَذَا الْعِلْمِ.", "segs": [{"ar": "فَهُمْ يَدَّعُونَ أَنَّهُمْ رِجَالُ الْحَدِيثِ،", "uz": "Ular o'zlarini hadis ahli deb da'vo qilishadi,"}, {"ar": "وَابْنُ سِرَاجٍ لَدَيْهِ مَعْرِفَةٌ وَاسِعَةٌ بِهَذَا الْعِلْمِ.", "uz": "Ibn Siroj esa bu ilmda keng bilimga ega."}], "full_uz": "Ular o'zlarini hadis ahli deb da'vo qilishadi, Ibn Siroj esa bu ilmda keng bilimga ega.", "note": null},
{"num": 401, "time": "00:34:30,579 --> 00:34:36,739", "arabic": "جِئْنِي بِهِ لِأَتَعَرَّفَ عَلَيْهِ.", "segs": null, "full_uz": "Uni olib kel, tanishib olay.", "note": null},
{"num": 402, "time": "00:34:36,739 --> 00:34:39,619", "arabic": "لَكَ ذَلِكَ.", "segs": null, "full_uz": "Xo'p bo'ladi.", "note": null},
{"num": 403, "time": "00:34:55,239 --> 00:34:56,759", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 404, "time": "00:34:56,759 --> 00:34:59,159", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.", "segs": null, "full_uz": "Va alaykum assalomu va rahmatullah.", "note": null},
{"num": 405, "time": "00:34:59,159 --> 00:35:03,879", "arabic": "أَهْلًا أَهْلًا بِأَبِي الْجَحْجَاحِ، أَهْلًا بِرَفِيقِ الصِّغَرِ.", "segs": null, "full_uz": "Xush kelibsiz, Abu al-Jahjah, xush kelibsiz, bolalik do'stim.", "note": null},
{"num": 407, "time": "00:35:03,879 --> 00:35:08,579", "arabic": "تَفَضَّلْ تَفَضَّلْ يَا أَخِي، كَيْفَ حَالُكَ؟", "segs": null, "full_uz": "Marhamat, marhamat, birodarim, ahvoling qalay?", "note": null},
{"num": 409, "time": "00:35:08,579 --> 00:35:11,299", "arabic": "أَهْلًا بِكَ يَا إِمَامَنَا وَقُرَّةَ عُيُونِنَا.", "segs": null, "full_uz": "Xush kelibsiz, imomimiz va ko'zimizning nuri.", "note": null},
{"num": 410, "time": "00:35:11,299 --> 00:35:14,839", "arabic": "أَحْمَدُ اللَّهَ عَلَى سَلَامَتِكَ يَا إِمَامُ.", "segs": null, "full_uz": "Sog'-omonligingiz uchun Allohga hamd aytaman, ey Imom.", "note": null},
{"num": 411, "time": "00:35:14,839 --> 00:35:25,899", "arabic": "قَدْ جِئْتُكَ وَرِجْلَايَ لَتُقَوِّيَانِي عَلَى حَمْلِي، فَرَقًا وَخَجَلًا مِنْكَ يَا أَبَا عَبْدِ اللَّهِ.", "segs": [{"ar": "قَدْ جِئْتُكَ وَرِجْلَايَ لَتُقَوِّيَانِي عَلَى حَمْلِي،", "uz": "Sizga zo'rg'a oyoqlarim meni ko'tarib kela olganicha keldim,"}, {"ar": "فَرَقًا وَخَجَلًا مِنْكَ يَا أَبَا عَبْدِ اللَّهِ.", "uz": "sizdan qo'rquv va uyat bilan, ey Abu Abdulloh."}], "full_uz": "Sizga zo'rg'a oyoqlarim meni ko'tarib kela olganicha keldim, sizdan qo'rquv va uyat bilan, ey Abu Abdulloh.", "note": null},
{"num": 413, "time": "00:35:25,899 --> 00:35:28,399", "arabic": "لَا تَقُلْ هَذَا يَا أَبَا الْجَحْجَاحِ.", "segs": null, "full_uz": "Bunday demang, ey Abu al-Jahjah.", "note": null},
{"num": 414, "time": "00:35:28,399 --> 00:35:38,219", "arabic": "عَسَى اللَّهُ أَنْ يَغْفِرَ لَكَ بِمَا قَدَّمْتَ، وَالْحَمْدُ لِلَّهِ الَّذِي أَبْعَدَكَ عَنْ مَوَاطِنِ الشُّبَهِ، وَرَدَّكَ إِلَى الْحَقِّ رَدًّا جَمِيلًا.", "segs": [{"ar": "عَسَى اللَّهُ أَنْ يَغْفِرَ لَكَ بِمَا قَدَّمْتَ،", "uz": "Alloh qilgan ishing uchun seni mag'firat qilishi ummid"}, {"ar": "وَالْحَمْدُ لِلَّهِ الَّذِي أَبْعَدَكَ عَنْ مَوَاطِنِ الشُّبَهِ،", "uz": "qilinadi. Seni shubha o'rinlaridan uzoqlashtirib,"}, {"ar": "وَرَدَّكَ إِلَى الْحَقِّ رَدًّا جَمِيلًا.", "uz": "haqqa go'zal qaytish bilan qaytargan Allohga hamd bo'lsin."}], "full_uz": "Alloh qilgan ishing uchun seni mag'firat qilishi ummid qilinadi. Seni shubha o'rinlaridan uzoqlashtirib, haqqa go'zal qaytish bilan qaytargan Allohga hamd bo'lsin.", "note": null},
{"num": 417, "time": "00:35:38,219 --> 00:35:48,219", "arabic": "هَذَا كَانَ بِفَضْلِ اللَّهِ، ثُمَّ بِفَضْلِكَ يَا أَبَا عَبْدِ اللَّهِ، جَزَاكَ اللَّهُ عَنِ الْإِسْلَامِ خَيْرًا.", "segs": [{"ar": "هَذَا كَانَ بِفَضْلِ اللَّهِ،", "uz": "Bu Allohning fazli bilan,"}, {"ar": "ثُمَّ بِفَضْلِكَ يَا أَبَا عَبْدِ اللَّهِ،", "uz": "so'ngra sizning fazlingiz bilan bo'ldi, ey Abu Abdulloh,"}, {"ar": "جَزَاكَ اللَّهُ عَنِ الْإِسْلَامِ خَيْرًا.", "uz": "Alloh Islom nomidan sizga yaxshilik bersin."}], "full_uz": "Bu Allohning fazli bilan, so'ngra sizning fazlingiz bilan bo'ldi, ey Abu Abdulloh, Alloh Islom nomidan sizga yaxshilik bersin.", "note": null},
{"num": 420, "time": "00:35:48,779 --> 00:35:58,219", "arabic": "وَمَنْ أَنَا حَتَّى يَجْزِيَ اللَّهُ الْإِسْلَامَ عَنِّي خَيْرًا؟ بَلْ جَزَى اللَّهُ الْإِسْلَامَ عَنَّا خَيْرًا فَهُوَ صَاحِبُ الْفَضْلِ وَلَوْلَاهُ مَا كُنَّا.", "segs": [{"ar": "وَمَنْ أَنَا حَتَّى يَجْزِيَ اللَّهُ الْإِسْلَامَ عَنِّي خَيْرًا؟", "uz": "Men kim edimki, Alloh Islom nomidan menga yaxshilik bersin?"}, {"ar": "بَلْ جَزَى اللَّهُ الْإِسْلَامَ عَنَّا خَيْرًا", "uz": "Aksincha, Alloh Islom nomidan bizga yaxshilik bersin,"}, {"ar": "فَهُوَ صَاحِبُ الْفَضْلِ وَلَوْلَاهُ مَا كُنَّا.", "uz": "chunki fazl egasi o'shadir, u bo'lmaganida biz ham bo'lmasdik."}], "full_uz": "Men kim edimki, Alloh Islom nomidan menga yaxshilik bersin? Aksincha, Alloh Islom nomidan bizga yaxshilik bersin, chunki fazl egasi o'shadir, u bo'lmaganida biz ham bo'lmasdik.", "note": null},
{"num": 422, "time": "00:36:11,219 --> 00:36:20,219", "arabic": "يَا ابْنَ السِّرَاجِ، هَذِهِ الْمُهِمَّةُ الَّتِي سَأُوكِلُهَا إِلَيْكَ فِي غَايَةِ الْخُطُورَةِ.", "segs": [{"ar": "يَا ابْنَ السِّرَاجِ،", "uz": "Ey Ibn Siroj,"}, {"ar": "هَذِهِ الْمُهِمَّةُ الَّتِي سَأُوكِلُهَا إِلَيْكَ فِي غَايَةِ الْخُطُورَةِ.", "uz": "senga topshirmoqchi bo'lgan bu vazifa juda xatarlidir."}], "full_uz": "Ey Ibn Siroj, senga topshirmoqchi bo'lgan bu vazifa juda xatarlidir.", "note": null},
{"num": 423, "time": "00:36:20,219 --> 00:36:35,219", "arabic": "فَالْخُزَاعِيُّ هَذَا رَجُلٌ مُتَفَقِّهٌ فِي عِلْمِ الْحَدِيثِ، هُوَ مُتَكَلِّمٌ وَجَرِيءٌ جِدًّا، يَعْلَمُ بِبَوَاطِنِ الْأُمُورِ، وَخَبِيرٌ بِمَعَادِنِ الرِّجَالِ.", "segs": [{"ar": "فَالْخُزَاعِيُّ هَذَا رَجُلٌ مُتَفَقِّهٌ فِي عِلْمِ الْحَدِيثِ،", "uz": "Bu Xuzoiy hadis ilmida chuqur bilimga ega,"}, {"ar": "هُوَ مُتَكَلِّمٌ وَجَرِيءٌ جِدًّا،", "uz": "u notiq va juda jasur, ishlarning ichki tomonini biladi,"}, {"ar": "يَعْلَمُ بِبَوَاطِنِ الْأُمُورِ، وَخَبِيرٌ بِمَعَادِنِ الرِّجَالِ.", "uz": "va odamlarning tabiatini yaxshi taniydi."}], "full_uz": "Bu Xuzoiy hadis ilmida chuqur bilimga ega, u notiq va juda jasur, ishlarning ichki tomonini biladi, va odamlarning tabiatini yaxshi taniydi.", "note": null},
{"num": 427, "time": "00:36:35,219 --> 00:36:42,559", "arabic": "وَأَخْشَى إِنْ عَلِمَ بِأَمْرِكَ أَنْ نَطِيحَ جَمِيعًا.", "segs": null, "full_uz": "Agar sening ishingdan xabar topsa, hammamiz qulab tushishimizdan qo'rqaman.", "note": null},
{"num": 428, "time": "00:36:42,559 --> 00:36:44,059", "arabic": "أَعَزَّ اللَّهُ الْأَمِيرَ.", "segs": null, "full_uz": "Alloh amirni aziz qilsin.", "note": null},
{"num": 429, "time": "00:36:44,059 --> 00:36:50,119", "arabic": "إِيَّاكَ، ابْنُ نَصْرٍ هَذَا لَا يَفُوقُنِي ذَكَاءً، فَهُوَ لَنْ يَصْعُبَ عَلَيَّ.", "segs": [{"ar": "إِيَّاكَ، ابْنُ نَصْرٍ هَذَا لَا يَفُوقُنِي ذَكَاءً،", "uz": "Xotirjam bo'ling, bu Ibn Nasr aqlda mendan ustun emas,"}, {"ar": "فَهُوَ لَنْ يَصْعُبَ عَلَيَّ.", "uz": "u menga qiyinchilik tug'dirmaydi."}], "full_uz": "Xotirjam bo'ling, bu Ibn Nasr aqlda mendan ustun emas, u menga qiyinchilik tug'dirmaydi.", "note": null},
{"num": 431, "time": "00:36:50,119 --> 00:36:57,359", "arabic": "مَا دَامَ قَدْ سَارَ فِي طَرِيقِ الضَّلَالِ، أَقْدِمْ وَأَرِحِ الْأَمِيرَ، وَسَتَعْلَمُونَ مَنْ هُوَ طَالِبُ السِّرَاجِ.", "segs": [{"ar": "مَا دَامَ قَدْ سَارَ فِي طَرِيقِ الضَّلَالِ،", "uz": "Adashish yo'lida yurgan ekan, oldinga bor va amirni tinchlantir,"}, {"ar": "أَقْدِمْ وَأَرِحِ الْأَمِيرَ،", "uz": "va"}, {"ar": "وَسَتَعْلَمُونَ مَنْ هُوَ طَالِبُ السِّرَاجِ.", "uz": "Tolib as-Siroj kimligini bilib olasizlar."}], "full_uz": "Adashish yo'lida yurgan ekan, oldinga bor va amirni tinchlantir, va Tolib as-Siroj kimligini bilib olasizlar.", "note": null},
{"num": 433, "time": "00:36:57,359 --> 00:37:05,960", "arabic": "بَلْ أَقْدِمْ وَأَرِحْنَا جَمِيعًا يَا طَالِبُ، لَا عَلَيْكَ، سَتَرَى مِنِّي فِي أَقْرَبِ وَقْتٍ مَا يَسُرُّ بَالَكَ.", "segs": [{"ar": "بَلْ أَقْدِمْ وَأَرِحْنَا جَمِيعًا يَا طَالِبُ،", "uz": "Balki oldinga borib, hammamizni tinchlantir,"}, {"ar": "لَا عَلَيْكَ،", "uz": "ey Tolib. Xavotir olma,"}, {"ar": "سَتَرَى مِنِّي فِي أَقْرَبِ وَقْتٍ مَا يَسُرُّ بَالَكَ.", "uz": "tez orada mendan ko'nglingni xursand qiladigan narsani ko'rasan."}], "full_uz": "Balki oldinga borib, hammamizni tinchlantir, ey Tolib. Xavotir olma, tez orada mendan ko'nglingni xursand qiladigan narsani ko'rasan.", "note": null},
{"num": 435, "time": "00:37:05,960 --> 00:37:12,919", "arabic": "يَبْدُو أَنَّ بَدْرًا لَمْ يُوَفِّكَ حَقَّكَ يَا ابْنَ السِّرَاجِ.", "segs": null, "full_uz": "Ko'rinishidan, Badr senga haqingni to'liq bermagan, ey Ibn Siroj.", "note": null},
{"num": 436, "time": "00:37:12,920 --> 00:37:23,599", "arabic": "هَمَسَ لِي أَحَدُهُمْ بِأَنَّكِ تَكْتُمِينَ عَنِّي سِرًّا.", "segs": null, "full_uz": "Birov menga sen mendan bir sirni yashiryapsan deb pichirladi.", "note": null},
{"num": 437, "time": "00:37:23,599 --> 00:37:27,440", "arabic": "سِرٌّ؟ أَيُّ سِرٍّ يَا خَالَتِي؟", "segs": null, "full_uz": "Sir? Qanday sir, ey xolajon?", "note": null},
{"num": 438, "time": "00:37:27,440 --> 00:37:29,380", "arabic": "سِرٌّ عَنِ ابْنِ إِسْحَاقَ فِي بَغْدَادَ.", "segs": null, "full_uz": "Bag'doddagi Ibn Ishoq haqidagi sir.", "note": null},
{"num": 439, "time": "00:37:29,380 --> 00:37:38,400", "arabic": "إِنِّي أُحِسُّ بِكِ كُلَّمَا نَظَرْتِ فِي عَيْنَيْهِ، وَلَمَحْتُ شُرُودًا يَحْتَوِيكِ.", "segs": [{"ar": "إِنِّي أُحِسُّ بِكِ كُلَّمَا نَظَرْتِ فِي عَيْنَيْهِ،", "uz": "Uning ko'zlariga qaraganingda seni his qilaman,"}, {"ar": "وَلَمَحْتُ شُرُودًا يَحْتَوِيكِ.", "uz": "va seni o'rab olgan bir xayolparastlikni sezdim."}], "full_uz": "Uning ko'zlariga qaraganingda seni his qilaman, va seni o'rab olgan bir xayolparastlikni sezdim.", "note": null},
{"num": 441, "time": "00:37:38,400 --> 00:37:41,360", "arabic": "ثُمَّ مَا الَّذِي يَدْعُوكِ إِلَى التَّكَتُّمِ؟", "segs": null, "full_uz": "Xo'sh, seni yashirishga nima undayapti?", "note": null},
{"num": 442, "time": "00:37:42,360 --> 00:37:44,360", "arabic": "لَيْسَ تَكَتُّمًا يَا خَالَةُ وَلَكِنْ...", "segs": null, "full_uz": "Yashirish emas, xolajon, lekin...", "note": null},
{"num": 443, "time": "00:37:44,360 --> 00:37:46,360", "arabic": "أَوَّلُ الْغَيْثِ قَطْرَةٌ.", "segs": null, "full_uz": "Yomg'irning boshi bir tomchidan boshlanadi.", "note": "\"أول الغيث قطرة\" — har bir katta ishning boshlanishi kichikdan bo'ladi, degan ma'nodagi arab maqoli."},
{"num": 444, "time": "00:37:47,360 --> 00:37:50,360", "arabic": "وَالنَّظَرُ بَرِيدُ الْحُبِّ وَرَسُولُ الْعِشْقِ يَا ابْنَتِي.", "segs": null, "full_uz": "Nigoh esa muhabbatning xabarchisi va ishqning elchisidir, qizim.", "note": null},
{"num": 445, "time": "00:37:51,360 --> 00:37:53,360", "arabic": "مِنْكِ نَتَعَلَّمُ يَا خَالَةُ.", "segs": null, "full_uz": "Sizdan o'rganamiz, xolajon.", "note": null},
{"num": 446, "time": "00:37:54,360 --> 00:38:01,360", "arabic": "ثُمَّ إِنَّهُ شَابٌّ لَا بَأْسَ بِهِ، لَقَدْ رَأَيْتُ نَظَرَاتِهِ تُلَاحِقُنِي غَيْرَ مَا مَرَّةٍ، فَمَا أَصْنَعُ؟", "segs": [{"ar": "ثُمَّ إِنَّهُ شَابٌّ لَا بَأْسَ بِهِ،", "uz": "Bundan tashqari, u yomon yigit emas,"}, {"ar": "لَقَدْ رَأَيْتُ نَظَرَاتِهِ تُلَاحِقُنِي غَيْرَ مَا مَرَّةٍ،", "uz": "uning nigohlari meni bir necha bor ta'qib qilganini ko'rdim,"}, {"ar": "فَمَا أَصْنَعُ؟", "uz": "endi nima qilay?"}], "full_uz": "Bundan tashqari, u yomon yigit emas, uning nigohlari meni bir necha bor ta'qib qilganini ko'rdim, endi nima qilay?", "note": null},
{"num": 449, "time": "00:38:01,360 --> 00:38:03,360", "arabic": "وَتَكْتُمِينَ عَنِّي؟", "segs": null, "full_uz": "Sen esa mendan yashiryapsanmi?", "note": null},
{"num": 450, "time": "00:38:03,360 --> 00:38:05,360", "arabic": "كَفَى إِحْرَاجًا يَا خَالَةُ.", "segs": null, "full_uz": "Xijolat qilishni bas qiling, xolajon.", "note": null},
{"num": 451, "time": "00:38:06,360 --> 00:38:16,360", "arabic": "فَأَنَا مُشَوَّشَةٌ قَلِيلًا، لَا أُنْكِرُ أَنَّنِي قَدِ ارْتَحْتُ لَهُ وَلَكِنْ لَا أَدْرِي بَعْدُ عَنْهُ.", "segs": [{"ar": "فَأَنَا مُشَوَّشَةٌ قَلِيلًا،", "uz": "Biroz sarosimadaman,"}, {"ar": "لَا أُنْكِرُ أَنَّنِي قَدِ ارْتَحْتُ لَهُ وَلَكِنْ لَا أَدْرِي بَعْدُ عَنْهُ.", "uz": "undan xotirjam bo'lganimni inkor etmayman, lekin haqida hali biror narsa bilmayman."}], "full_uz": "Biroz sarosimadaman, undan xotirjam bo'lganimni inkor etmayman, lekin haqida hali biror narsa bilmayman.", "note": null},
{"num": 453, "time": "00:38:38,360 --> 00:38:44,400", "arabic": "الْحَمْدُ لِلَّهِ عَلَى سَلَامَتِكَ يَا إِمَامُ.", "segs": null, "full_uz": "Sog'-omonligingiz uchun Allohga hamd bo'lsin, ey Imom.", "note": null},
{"num": 456, "time": "00:38:49,760 --> 00:38:56,720", "arabic": "نَحْمَدُ اللَّهَ عَلَى رُؤْيَتِكَ فِي الْمَسْجِدِ ثَانِيَةً، بَيْنَ طُلَّابِكَ وَمُحِبِّيكَ يَا أَبَا عَبْدِ اللَّهِ.", "segs": [{"ar": "نَحْمَدُ اللَّهَ عَلَى رُؤْيَتِكَ فِي الْمَسْجِدِ ثَانِيَةً،", "uz": "Sizni yana masjidda, shogirdlaringiz va sizni sevuvchilar orasida"}, {"ar": "بَيْنَ طُلَّابِكَ وَمُحِبِّيكَ يَا أَبَا عَبْدِ اللَّهِ.", "uz": "ko'rganimiz uchun Allohga hamd aytamiz, ey Abu Abdulloh."}], "full_uz": "Sizni yana masjidda, shogirdlaringiz va sizni sevuvchilar orasida ko'rganimiz uchun Allohga hamd aytamiz, ey Abu Abdulloh.", "note": null},
{"num": 458, "time": "00:38:56,720 --> 00:38:59,960", "arabic": "الْحَمْدُ لِلَّهِ عَلَى كُلِّ شَيْءٍ.", "segs": null, "full_uz": "Hamma narsa uchun hamd Allohga xosdir.", "note": null},
{"num": 459, "time": "00:38:59,960 --> 00:39:01,480", "arabic": "تَعْسًا لِمَنْ كَانَ السَّبَبَ فِي ذَلِكَ.", "segs": null, "full_uz": "Bunga sabab bo'lganga halokat bo'lsin.", "note": null},
{"num": 460, "time": "00:39:01,480 --> 00:39:05,280", "arabic": "بَلْ غَفَرَ اللَّهُ لَهُمْ جَمِيعًا وَهَدَاهُمْ.", "segs": null, "full_uz": "Aksincha, Alloh ularning barchasini mag'firat qilib, hidoyat qilsin.", "note": null},
{"num": 461, "time": "00:39:05,280 --> 00:39:08,780", "arabic": "أَلَا تَدْعُو عَلَى الظَّلَمَةِ يَا إِمَامُ؟", "segs": null, "full_uz": "Zolimlarga qarshi duo qilmaysizmi, ey Imom?", "note": null},
{"num": 462, "time": "00:39:08,780 --> 00:39:16,480", "arabic": "مَا صَبَرَ مَنْ دَعَا عَلَى ظُلْمِهِ يَا وَلَدِي.", "segs": null, "full_uz": "O'ziga qilingan zulmga qarshi duo qilgan kishi sabr qilmagan bo'ladi, o'g'lim.", "note": null},
{"num": 464, "time": "00:39:35,280 --> 00:39:51,720", "arabic": "لَيْتَ عُمَرَ الْإِسْكَافِيَّ تَقَدَّمَ لِلزَّوَاجِ مِنْكِ مُنْذُ زَمَنٍ، حَتَّى أَرَى كُلَّ هَذَا الْفَرَحِ فِي عَيْنَيْكِ.", "segs": [{"ar": "لَيْتَ عُمَرَ الْإِسْكَافِيَّ تَقَدَّمَ", "uz": "Qani edi,"}, {"ar": "لِلزَّوَاجِ مِنْكِ مُنْذُ زَمَنٍ،", "uz": "Umar al-Iskofiy sizga ancha oldin turmushga chiqishni taklif qilganida,"}, {"ar": "حَتَّى أَرَى كُلَّ هَذَا الْفَرَحِ فِي عَيْنَيْكِ.", "uz": "shunda ko'zlaringizdagi bu quvonchni ancha oldin ko'rgan bo'lardim."}], "full_uz": "Qani edi, Umar al-Iskofiy sizga ancha oldin turmushga chiqishni taklif qilganida, shunda ko'zlaringizdagi bu quvonchni ancha oldin ko'rgan bo'lardim.", "note": null},
{"num": 467, "time": "00:39:51,720 --> 00:39:55,019", "arabic": "إِنْ أَرَدْتِ الْحَقَّ، فَرْحَتِي لَمْ تَكْتَمِلْ.", "segs": null, "full_uz": "Rostini aytsam, mening quvonchim to'liq emas.", "note": null},
{"num": 469, "time": "00:39:55,019 --> 00:39:59,260", "arabic": "لِأَنَّ أُخْتِي فَوْزَ لَمْ تَسْتَطِعِ الْحُضُورَ لِتُشَارِكَنِي فَرْحَةَ عُمْرِي.", "segs": null, "full_uz": "Chunki singlim Fawz umrimdagi bu quvonchimga sherik bo'lish uchun kela olmadi.", "note": null},
{"num": 471, "time": "00:39:59,260 --> 00:40:01,519", "arabic": "مَعْذِرَةً يَا ابْنَتِي.", "segs": null, "full_uz": "Uzr, qizim.", "note": null},
{"num": 472, "time": "00:40:01,519 --> 00:40:05,880", "arabic": "فَدِمَشْقُ لَيْسَتْ بِالْبَلَدِ الْقَرِيبِ، وَأَيْضًا مَشَاغِلُ زَوْجِهَا كَثِيرَةٌ.", "segs": null, "full_uz": "Damashq yaqin joy emas, shuningdek, uning erining ishlari ham ko'p.", "note": null},
{"num": 474, "time": "00:40:05,880 --> 00:40:14,400", "arabic": "أَلَمْ تَنْتَهُوا بَعْدُ؟", "segs": null, "full_uz": "Hali tugatmadinglarmi?", "note": null},
{"num": 475, "time": "00:40:14,400 --> 00:40:17,720", "arabic": "لَقَدِ اقْتَرَبَ مَوْعِدُ وُصُولِ أَهْلِ عُمَرَ الْإِسْكَافِيِّ.", "segs": null, "full_uz": "Umar al-Iskofiyning oila a'zolari kelish vaqti yaqinlashdi.", "note": null},
{"num": 476, "time": "00:40:17,720 --> 00:40:19,440", "arabic": "لَحَظَاتٌ وَنَنْتَهِي.", "segs": null, "full_uz": "Bir necha lahza, tugatamiz.", "note": null},
{"num": 477, "time": "00:40:20,920 --> 00:40:36,579", "arabic": "إِنَّنِي أُفَكِّرُ فِي تَزْوِيجِهِ يَا عَبَّاسَةُ، أَلَيْسَ بَاكِرًا أَنْ أَتَحَدَّثَ فِي هَذَا الْأَمْرِ؟", "segs": [{"ar": "إِنَّنِي أُفَكِّرُ فِي تَزْوِيجِهِ يَا عَبَّاسَةُ،", "uz": "Uni uylantirish haqida o'ylayapman,"}, {"ar": "أَلَيْسَ بَاكِرًا أَنْ أَتَحَدَّثَ فِي هَذَا الْأَمْرِ؟", "uz": "ey Abbasa, bu haqda gapirish erta emasmi?"}], "full_uz": "Uni uylantirish haqida o'ylayapman, ey Abbasa, bu haqda gapirish erta emasmi?", "note": null},
{"num": 479, "time": "00:40:36,579 --> 00:40:50,220", "arabic": "لَا أَكْتُمُكِ سِرًّا أَنَّنِي مُنْذُ أَنْ أَخْرَجَنِيَ اللَّهُ مِنَ السِّجْنِ، وَأَنَا أَخْشَى أَنْ أَمُوتَ قَبْلَ أَنْ أَرَى أَبْنَاءَ وَلَدِي صَالِحٍ فِي ذَاتِ نَفْسِي.", "segs": [{"ar": "لَا أَكْتُمُكِ سِرًّا أَنَّنِي مُنْذُ", "uz": "Sendan sirni yashirmayman: Alloh"}, {"ar": "أَنْ أَخْرَجَنِيَ اللَّهُ مِنَ السِّجْنِ،", "uz": "meni qamoqdan chiqarganidan beri,"}, {"ar": "وَأَنَا أَخْشَى أَنْ أَمُوتَ قَبْلَ أَنْ أَرَى أَبْنَاءَ", "uz": "o'g'lim Solihning farzandlarini ko'rmasdan o'lib qolishimdan"}, {"ar": "وَلَدِي صَالِحٍ فِي ذَاتِ نَفْسِي.", "uz": "ichimda qo'rqib yuraman."}], "full_uz": "Sendan sirni yashirmayman: Alloh meni qamoqdan chiqarganidan beri, o'g'lim Solihning farzandlarini ko'rmasdan o'lib qolishimdan ichimda qo'rqib yuraman.", "note": null},
{"num": 482, "time": "00:40:50,220 --> 00:40:52,460", "arabic": "لِمَاذَا تَقُولُ هَذَا الْكَلَامَ؟", "segs": null, "full_uz": "Nega bunday gapirasiz?", "note": null},
{"num": 483, "time": "00:40:52,460 --> 00:40:54,679", "arabic": "أَطَالَ اللَّهُ فِي عُمْرِكَ.", "segs": null, "full_uz": "Alloh umringizni uzun qilsin.", "note": null},
{"num": 484, "time": "00:40:54,679 --> 00:40:58,539", "arabic": "الْمَوْتُ قَدَرٌ لَا بُدَّ مِنْهُ.", "segs": null, "full_uz": "O'lim — muqarrar taqdirdir.", "note": null},
{"num": 485, "time": "00:40:58,539 --> 00:41:02,000", "arabic": "أُرِيدُكِ أَنْ تَجِدِي لَهُ فَتَاةً مِنْ بَيْتٍ يُشْبِهُنَا.", "segs": null, "full_uz": "Sendan unga bizga o'xshash uydan bir qiz topishingni istayman.", "note": null},
{"num": 486, "time": "00:41:03,440 --> 00:41:08,920", "arabic": "إِنَّ أَكْبَرَ بُيُوتَاتِ بَغْدَادَ يَحْلُمُونَ بِمُصَاهَرَتِكَ يَا أَبَا عَبْدِ اللَّهِ.", "segs": [{"ar": "إِنَّ أَكْبَرَ بُيُوتَاتِ بَغْدَادَ يَحْلُمُونَ", "uz": "Bag'dodning eng katta xonadonlari siz bilan"}, {"ar": "بِمُصَاهَرَتِكَ يَا أَبَا عَبْدِ اللَّهِ.", "uz": "quda bo'lishni orzu qiladi, ey Abu Abdulloh."}], "full_uz": "Bag'dodning eng katta xonadonlari siz bilan quda bo'lishni orzu qiladi, ey Abu Abdulloh.", "note": null},
{"num": 487, "time": "00:41:08,920 --> 00:41:16,139", "arabic": "وَلَكِنِّي أُرِيدُ لِصَالِحٍ فَتَاةً مِنْ ثَوْبِهِ وَثَوْبِ أَهْلِهِ، حَتَّى لَا تُتْعِبَهُ وَلَا نَشُقَّ عَلَيْهَا.", "segs": [{"ar": "وَلَكِنِّي أُرِيدُ لِصَالِحٍ فَتَاةً مِنْ ثَوْبِهِ وَثَوْبِ أَهْلِهِ،", "uz": "Lekin men Solihga o'z darajasidagi va o'z oilasi darajasidagi qizni istayman,"}, {"ar": "حَتَّى لَا تُتْعِبَهُ وَلَا نَشُقَّ عَلَيْهَا.", "uz": "toki uni charchatmasin va biz ham unga og'irlik qilmaylik."}], "full_uz": "Lekin men Solihga o'z darajasidagi va o'z oilasi darajasidagi qizni istayman, toki uni charchatmasin va biz ham unga og'irlik qilmaylik.", "note": null},
{"num": 489, "time": "00:41:16,139 --> 00:41:22,800", "arabic": "مَا نَنُوءُ لِأَهْلِ الْجَاهِ وَالثَّرْوَةِ، كَمْ تُحَاوِلُ أَنْ تَكُونَ مِنْ عَامَّةِ النَّاسِ.", "segs": [{"ar": "مَا نَنُوءُ لِأَهْلِ الْجَاهِ وَالثَّرْوَةِ،", "uz": "Biz martaba va boylik ahliga moyil emasmiz,"}, {"ar": "كَمْ تُحَاوِلُ أَنْ تَكُونَ مِنْ عَامَّةِ النَّاسِ.", "uz": "qanchalik oddiy xalqdan bo'lishga harakat qilasiz."}], "full_uz": "Biz martaba va boylik ahliga moyil emasmiz, qanchalik oddiy xalqdan bo'lishga harakat qilasiz.", "note": null},
{"num": 491, "time": "00:41:22,800 --> 00:41:29,280", "arabic": "وَلَكِنْ يَأْبَى اللَّهُ إِلَّا أَنْ يَزْدَادَ صِيتُكَ بَيْنَ النَّاسِ، وَتَكْبُرَ مَحَبَّتُكَ فِي قُلُوبِ الْمُسْلِمِينَ.", "segs": [{"ar": "وَلَكِنْ يَأْبَى اللَّهُ إِلَّا أَنْ يَزْدَادَ صِيتُكَ بَيْنَ النَّاسِ،", "uz": "Lekin Alloh sizning shuhratingiz odamlar orasida ortishini va"}, {"ar": "وَتَكْبُرَ مَحَبَّتُكَ فِي قُلُوبِ الْمُسْلِمِينَ.", "uz": "muhabbatingiz musulmonlarning qalbida kattalashishini xohlaydi."}], "full_uz": "Lekin Alloh sizning shuhratingiz odamlar orasida ortishini va muhabbatingiz musulmonlarning qalbida kattalashishini xohlaydi.", "note": null},
{"num": 493, "time": "00:41:29,280 --> 00:41:36,800", "arabic": "أَرْجُو أَنْ لَا يَكُونَ ذَلِكَ مِنَ اللَّهِ لَنَا اسْتِدْرَاجًا، أَرْجُو أَنْ لَا يَكُونَ اسْتِدْرَاجًا.", "segs": [{"ar": "أَرْجُو أَنْ لَا يَكُونَ ذَلِكَ مِنَ اللَّهِ لَنَا اسْتِدْرَاجًا،", "uz": "Umid qilamanki, bu Allohning bizga istidraji (asta-sekin halokatga yetaklashi) bo'lmasin,"}, {"ar": "أَرْجُو أَنْ لَا يَكُونَ اسْتِدْرَاجًا.", "uz": "umid qilamanki, istidraj bo'lmasin."}], "full_uz": "Umid qilamanki, bu Allohning bizga istidraji (asta-sekin halokatga yetaklashi) bo'lmasin, umid qilamanki, istidraj bo'lmasin.", "note": null},
{"num": 495, "time": "00:41:36,800 --> 00:41:43,620", "arabic": "فَإِنْ كَانَ الشَّرُّ فِتْنَةً وَبَلْوَى، فَالْخَيْرُ أَشَدُّ فِتْنَةً وَأَمَضُّ بَلْوَى.", "segs": [{"ar": "فَإِنْ كَانَ الشَّرُّ فِتْنَةً وَبَلْوَى،", "uz": "Agar yomonlik fitna va sinov bo'lsa,"}, {"ar": "فَالْخَيْرُ أَشَدُّ فِتْنَةً وَأَمَضُّ بَلْوَى.", "uz": "yaxshilik undan ham qattiqroq fitna va og'riqliroq sinovdir."}], "full_uz": "Agar yomonlik fitna va sinov bo'lsa, yaxshilik undan ham qattiqroq fitna va og'riqliroq sinovdir.", "note": null},
{"num": 497, "time": "00:41:43,620 --> 00:41:48,180", "arabic": "قَالَ تَعَالَى: وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً.", "segs": null, "full_uz": "Alloh taolo aytadi: \"Sizlarni yomonlik va yaxshilik bilan sinov tariqasida sinaymiz.\"", "note": "Qur'on, Anbiyo surasi, 35-oyat."}
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}